-- The 69 super abilities of Revised Heroes Unlimited: 31 minor, 38 major.
-- Printed 163-192. The first rows in `super_abilities`, which migration 057
-- created for exactly this and which held nothing until now.
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-hu-core-super-abilities.sql
--
-- THE ROSTER IS CONFIRMED TWICE, which is why the names are trustworthy even
-- where the OCR of a heading is not. The book prints each roster in two places:
-- the RANDOM tables on printed 163 (31 minor, 38 major, each with a percentile
-- range) and the ALPHABETICAL lists on printed 163 and 169. Every name in one
-- appears in the other, in both directions.
--
-- NAMES COME FROM THE INDEX, NOT THE HEADING - book-survey section 4c - and on
-- this book that is not a formality. FIVE of the 69 are set differently where
-- they are described than where they are indexed:
--
--   index                                  heading above the description
--   Impervious to Fire & Heat              Impervious to Fire and Heat
--   Super Vision: Ultraviolet & Infrared   Super Vision: Ultraviolet/infrared
--   Control Elemental Force: Earth         Control Elemental Forces: Earth (plural)
--   Control Others                         Control (Others)
--   Shape Change                           Shape-Changer
--
-- and two more differ between the book's OWN two rosters, where the
-- alphabetical list carries a parenthetical the random table omits: Sonic Speed
-- (running) and Stretching (elasticity). The indexed spelling is stored; the
-- heading spellings were only ever used to FIND the block.
--
-- HOW THE BLOCKS WERE SLICED. By known name, taking each block from its heading
-- to the next name. Every name occurs three or four times in printed 163-192 -
-- twice in the random tables, once in an alphabetical list, once as its real
-- heading - so the occurrence is chosen by scoring how much PROSE follows it
-- before the next name. A roster line scores zero or one; a description scores
-- tens. Two simpler rules were tried first and both failed in OPPOSITE
-- directions: rejecting on the FOLLOWING line misses a list's last entry, and
-- rejecting on the PRECEDING line misses the first description after a list.
-- The second mistake gave Weight Manipulation a one-line block twenty-two pages
-- early, on printed 169, which is why there is an assertion about it below.
--
-- NO COST AND NO LEVEL, which is the whole reason this table exists. The stat
-- block columns carry what the book prints; where it prints nothing the column
-- is NULL rather than invented.
--
-- LABELS WITH NO COLUMN ARE KEPT IN THE DESCRIPTION, IN PLACE, in the book's
-- own order: Bonuses, Restrictions, Limitations, Note, "Other Abilities and
-- Bonuses". They are mechanically load-bearing - "Bonuses: Increase P.S. to
-- 20+1D6" IS the ability - and dropping them would leave a row that describes
-- a power without saying what it does.
--
-- A FIELD VALUE RUNS TO THE NEXT LABEL, not to the end of its line. Taking one
-- line was the first version, and it split every multi-line Restrictions and
-- Bonuses in the book, stranding the continuation at the END of the
-- description, detached from its own label. Adhesion read "Restrictions: ...
-- ice, oil or other Other Abilities and Bonuses: Automatic climbing skill equal
-- Characters with this power are able to... slippery substances".
--
-- OCR LINE-WRAP HYPHENS ARE REJOINED, between LETTERS ONLY - "pick poc- ket"
-- becomes "pick pocket". book-survey section 0e: a hyphen BETWEEN DIGITS is a
-- RANGE, and a word-rejoiner let near "20,000- 30,000" makes 2,000,030,000.
-- The rule was tested both directions before it was run over 69 descriptions.
--
-- THREE ROWS ARE GENUINELY SHORT and are not truncated: Extraordinary Physical
-- Strength, Impervious to Fire & Heat and Super Vision: Nightvision run to two
-- or three lines in the book. Checked against the pages.
--
-- ONE INSERT PER ROW, not one statement with 69 tuples: D1 rejects that with
-- SQLITE_TOOBIG. These descriptions total about 118,000 characters and the
-- longest single one is 7,610. An earlier draft of the generator also capped
-- each description at 4,000 characters, which silently dropped about 12,000
-- characters of book text across seven rows. There is no cap now.
--
-- Curly quotes, em-dashes and OCR replacement characters are folded to ASCII,
-- per d1-apply's pure-ASCII pre-flight.

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Adhesion', 'minor', 'import', 'Revised Heroes Unlimited p.163', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'Characters with this power are able to attach themselves to any solid surface by their fingers and hands, toes and feet. This means that the person can walk on walls or ceilings, can climb any surface effortlessly, and is terrific at catching fly balls. The only limits to this power are the character''s own strength and speed. Attempting to carry a heavy load greater than his/her P.S. X 10 in pounds, will cause the character to immediately fall off. Speed climbing is equal to HALF the running speed. This also applies to movement on walls and ceilings. Restrictions: Loose rocks, crumbling plaster, ice, oil or other slippery substances will prevent the character from adhering to a surface. Other Abilities and Bonuses: Automatic climbing skill equal to 90% proficiency (does not include rappelling). Add + 10% to Prowl when climbing on ceiling. Add + 30% to pick pocket, palming and concealment.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Bend Light', 'minor', 'import', 'Revised Heroes Unlimited p.164', 'heroes-unlimited', 'Self or Light Beam - 100ft', 'One melee', 'None', NULL, 'The ability to bend light allows the character to manipulate light radiation like a prism. This can produce a number of effects. 1. Separate the color bands of light to produce a colored light beam or radiate about 70 watts of colored light (enough to light up a 10 10ft room). The colors possible are red, yellow, blue, green, purple, orange, as well as infrared and ultraviolet. Range: Of the beam is 100ft (30.5m); does no damage. 2. Parries lasers and other light beams by bending the light around him, or a 10ft area, to deflect the beam. Roll just like a normal parry. 3. Can see into the infrared and ultraviolet light range. 100ft (30.5m) is the maximum distance.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Energy Expulsion: Energy', 'minor', 'import', 'Revised Heroes Unlimited p.164', 'heroes-unlimited', '600ft maximum (183m)', 'Instant', '2D6+1D6 for each level of experience.', NULL, 'Attacks Per Melee: Same as hand to hand. Each blast counts as one hand to hand attack or action for that melee. Bonuses: +3 tostrike if an aimed shot, + | tostrike if shooting wild. The character can generate energy which can be released in directed pulses. The energy pulse or blast is fired from the fingertips, hand or eyes. More powerful, experienced characters (3rd level and higher) can regulate the strength of each blast in increments of 1D6. For Example: A 6th level hero can fire blasts doing as much as 8D6; that''s 8 to 48 points of damage at maximum strength. However, his mastery over his power enables him to fire a warning shot doing a mere 1D6, a firmer 2D6, a don''t push your luck 3D6, a forceful 4D6, a rock-em 5D6, a heavy 6D6, a powerful 7D6 or a full force 8D6 blast. The power behind the energy blast does not affect the character in any way. Note: The ability to regulate the force of a blast applies to ALL energy expulsion powers.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Energy Expulsion: Fire', 'minor', 'import', 'Revised Heroes Unlimited p.164', 'heroes-unlimited', '60ft maximum (18.3m)', 'Instant', '2D6+ 1D6 for each level of experience.', NULL, '164 Attacks Per Melee: Same as hand to hand. + 3 to strike if an aimed shot, + 1 to strike if shooting Bonuses: wild. The character can emit a flamethrower-like blast from his hands, Like the previous energy expulsion, the severity of damage can be controlled in increments of 1D6. Remember, maximum damage is limited by the level of experience. Range is limited to 60ft,');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Energy Expulsion: Electricity', 'minor', 'import', 'Revised Heroes Unlimited p.164', 'heroes-unlimited', '400ft maximum (122m)', 'Instant', '3D6+ 1D6 for each level of experience.', NULL, 'Attacks Per Melee: Same as hand to hand. Bonuses: +3 to strike if an aimed shot, + | to strike if shooting wild. Electrical energy bolts leap from the fingers of this living electrical generator. As the character grows in experience (3rd level and higher), he/she can regulate the degree of damage by increments of 1D6. >');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Energy Expulsion: Electrical Field', 'minor', 'import', 'Revised Heroes Unlimited p.165', 'heroes-unlimited', '10ft area plus an additional 2ft per each level of experi- ence.', 'One full melee (can be instantly renewed).', '4D6 for every 5 seconds within the energy field.', NULL, 'Attacks Per Melee: One long continuous attack. No other attacks or actions can be made while the electrical field is up. Bonuses: +2 tostrike. No aimed shot is possible; area affect. This character can turn himself into a living dynamo, crackling with electrical energy. Standing stationary, the hero can generate a field of electricity around himself affecting everyone within a 12ft area (first level). Victims caught in the field will suffer a maximum of 4D6 damage for every FIVE seconds trapped in the field (equal to 3 attacks per melee). Experienced characters (3rd level and higher) can diminish the field''s damage to as little as 1D6 per five seconds of exposure. While the field is up the character is impervious to electrical and energy attacks. Projectiles, bullets and thrown objects are minus - 8 to strike, but do full damage if they hit. Fire is not hampered by the electrical field. Note: The damage of the field does NOT increase with experience or age.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Energy Expulsion: Light', 'minor', 'import', 'Revised Heroes Unlimited p.165', 'heroes-unlimited', '600ft (183m)', 'Instant', '2D6 + 1D6 per each level of experience.', NULL, 'Attacks Per Melee: Same as hand to hand. Bonuses: +3 to strike for aimed shot. +1 if shooting wild. The ability to draw on light energy/radiation and emit a highly concentrated bolt of light, not unlike a laser beam. The light bolt can only be fired in pulses from the fingers, hands or eyes. With experience (3rd level or higher), the character can regulate the amount of damage inflicted by the light bolt in increments of 1D6. The character can also radiate light like a human light bulb. Equal to about 100 watts, plus 25 watts per level of experience. Even at first level he can radiate enough to light up a 20 x 20ft room.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Energy Resistance', 'minor', 'import', 'Revised Heroes Unlimited p.165', 'heroes-unlimited', 'Self', 'Constant', NULL, NULL, 'Attacks Per Melee: None Bonuses: None This power makes the character extremely resistant to all energy based attacks. No physical damage is sustained by the first 20 points of energy attacks in a melee round. Energy attacks beyond the 20 points do only half damage. The character''s resistance to energy includes fire, electricity, lasers and pure energy. The person is completely invulnerable to stun-type energy weapons. Energy resistance is not effective against radiation damage.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Extraordinary Mental Affinity', 'minor', 'import', 'Revised Heroes Unlimited p.165', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'An aura of likability, confidence and trust radiates from this character. He or she is so dynamic that they are often the center of attention and make the opposite sex swoon. Bonuses: Increase M.A. to 24+ 1D6. Skill bonus of + 10% is added to pick pockets and all skills of deception and sleight of hand.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Extraordinary Mental Endurance', 'minor', 'import', 'Revised Heroes Unlimited p.165', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'A very mentally stable and strong personality that is difficult to suppress or break. This guy has a will of iron. Bonuses: Increase M.E. to 20+2D4. Note the resistance to psionic attacks (see Attribute Bonus Table). The same bonus applies to all mind altering magic and drugs.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Extraordinary Physical Strength', 'minor', 'import', 'Revised Heroes Unlimited p.165', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'This character possesses astounding physical strength. Bonuses: Increase P.S, to 20+ 1D6. Can carry 100 times (not 50) P.S. in pounds and can lift 200 times (not 100) P.S. in pounds.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Extraordinary Physical Prowess', 'minor', 'import', 'Revised Heroes Unlimited p.165', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'A greatly heightened physical prowess providing increased speed and agility. Bonuses: Add 2D4 to the P.P. attribute. Add 3D4 to the Speed attribute. Add one extra attack per melee. Plus 10% to physical skills requiring dexterity and prowess, such as prowl, gymnastics, etc.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Extraordinary Physical Endurance', 'minor', 'import', 'Revised Heroes Unlimited p.165', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'An extremely tough individual who can withstand a great amount of physical strain or punishment. Bonuses: Add 2D6 to the P.E. attribute; take note of bonuses to save vs toxins and coma. See attribute bonuses. Add 4D4 x 10 .D.C.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Extraordinary Physical Beauty', 'minor', 'import', 'Revised Heroes Unlimited p.165', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'Anextremely attractive individual whose beauty is truly exceptional. Members of the opposite sex are particularly vulnerable to this character''s charm. Bonuses: Increase P.B. to 20+2D4, See attribute bonuses for the ability to impress and charm. + 10% to interrogation and pick pocket skills.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Extraordinary Speed', 'minor', 'import', 'Revised Heroes Unlimited p.165', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'The ability to move and run faster than most vehicles without tiring. Bonuses: Speed 220mph (353kmph), plus 20 miles (32km) per level of experience. Add one extra attack per melee. Add 50 to .D.C. Add +2 on initiative. Add +72 to strike. Add +6 to parry. Add +6 to dodge. Add +4 to roll with punch or fall. Add + 4 to inflict damage for every 20mph of speed. Note: The best a punch or kick can do from a standing still position is 40mph (64kmph) adding +8 to damage. =');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Flight: Glide', 'minor', 'import', 'Revised Heroes Unlimited p.166', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'This power allows the super being to ride air currents and hover. Maximum gliding speed outdoors, with a strong wind or from a great height (jumping out of an airplane or yi ipa s rooftop), is 120mph (192kmph). However, a typical speed is more likely to be 40 to 50mph (64 to 80kmph). Gliding indoors is more difficult, with a maximum speed of 40mph (64kmph) and an average speed of 15mph (24km). Bonuses When Gliding: Add +2 to strike. Add +2 to parry. Add +2 to dodge. > / \ ef AN');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Flight: Winged', 'minor', 'import', 'Revised Heroes Unlimited p.166', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'This super being has physical wings that give him the power of flight, Unfortunately, wings are difficult to conceal. This can make a secret identity a bit of a problem. However, wings can be carefully folded, tucked and restrained with minimal discomfort. Wings that are pulled back and strapped in place impairs the characters mobility. Penalties: When Wings are Restrained: Subtract - | on initiative. Subtract - 1 Lo parry. Subtract - | to dodge. Subtract one attack per melee. Bonuses In Flight: Speed - |60mph (256kmph) plus 1Omph (16kmph) per level of experience. Add one attack per melec. Add +2 to strike. Add +2 to parry. Add +4 to dodge when hovering or flying less than 80mph; + 6 to dodge when flying around 90mph or faster. Add +4 to damage for every 20mph of flight speed. Other Bonuses: Add +40 to S.D.C. Type of Wings: 1-35 Leather 36-70 Feather 71-00 Insect');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Flight: Wingless', 'minor', 'import', 'Revised Heroes Unlimited p.166', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'The impressive ability to fly without any apparent means of propulsion. Bonuses In Flight: Speed 200mph (321kmph), plus 20mph per level of experience. Add one attack per melee. . Add +72 to strike. Add +2 to parry. Add +4 to dodge when hovering or flying less than 80mph; + 6 to dekdlge when flying around 90mph or faster. Add +4 to damage for every 20mph of flight speed. Other Bonuses: Add +40 to .D.C.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Healing Factor', 'minor', 'import', 'Revised Heroes Unlimited p.166', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'This power provides incredible recuperative abilities and immunity to disease and toxins. Bonuses: Add 2D4 to the P.E. attribute. Add 25 to .D.C. Add +20% to save vs coma/death. Add +3 to save vs magic, psionics and toxins (this is in addition to the P,E. bonuses). The Healing Factor: Recovers 3 .D.C. every 10 minutes (18 per hour). @ Recovers one hit point every 15 minutes (4 per hour). Special super healing: Can instantly regenerate 2D6 hit points TWO times per day (24 hour period). Doe NOT fatigue. @ Resistant to fire and cold; does half damage. Resistant to drugs, toxins, poison; ''/4 as effective; 4 damage, No scarring when healed. Broken bones heal completely, without any sign of having ever been broken. Heals 10 times faster than normal.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Heightened Sense of Hearing', 'minor', 'import', 'Revised Heroes Unlimited p.166', 'heroes-unlimited', '360ft radius (109.8m)', NULL, NULL, NULL, 'Heightened hearing enables the character to hear tiny, almost inaudible, sounds several hundred feet away. At 75ft (22.9m) he can hear sounds as quiet as one decibel. At 150ft (45.8m) he can hear sounds as quiet as 10 decibels. At 360ft the audible perception is greatly taxed, allowing him to barely hear a normal conversation in the 30 decibel range. See Sonic Power for the decibel scale. Loud or constant noise will reduce the quality of hearing perception. If surrounding noise is in the 70 decibel area the hearing range will be reduced by 10 feet. Continue to reduce by Sft for every additional 10 decibels. Other Abilities Include: Estimating the distance of the sound at a 60% + 5% per level proficiency; estimating the speed of the sound''s approach or departure at 50% + 5% per level of experience; recognize a voice or sound through intense concentration at 40% + 5% per level of experience; and imitate a voice at a 35% +5% per level of experience. Bonuses: +1 to parry. +2 to dodge. +6 on initiative. Heightened Sense of Sight See Super Vision.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Heightened Sense of Smell', 'minor', 'import', 'Revised Heroes Unlimited p.167', 'heroes-unlimited', '90ft An exceptional sense of smell that can identify any smell', NULL, NULL, NULL, 'within 90ft (27.4m) of the character. Abilities: Recognize/identify specific odors: 70% +4% per level of expericnee. @ Recognize a person by scent alone: 50% +5% per level of experience. @ Recognize poisons and toxins: 50% + 5% per level of experience. Note: Some poison gases are odorless/tasteless/colorless. Track by smell: 40% + 5% per level of experience. Reduce by 10% in the city. Roll for every 200 yards.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Heightened Sense of Taste', 'minor', 'import', 'Revised Heroes Unlimited p.167', 'heroes-unlimited', 'Touch/Taste Having a heightened sense of taste means being able to exactly', NULL, NULL, NULL, 'identify the components in anything tasted. The presence of drugs or chemicals in food will be immediately apparent, although identifying the particular drug or chemical depends on the character''s skill in pharmaceutical or chemistry. Characters with heightened sense of taste will tend to be very particular about what they eat or drink. With practice, they can exactly identily the components and source of any food or drink. For example, if a character studies wine then he/she will eventually be able to identify the type, year, bottling company, and vineyard of any wine from a single taste. @ Recognize common items, such as sugar, salt, pepper, spices, gasoline, and similar, at a proficiency of 70% + 4% per level of experience. @ Recognize exotic tastes such as chemicals, toxins and poisons al a proficiency of 30% + 5% per level of experience. Practicing to recognize an unusual taste for two months will put that taste into the common item category.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Heightened Sense of Touch', 'minor', 'import', 'Revised Heroes Unlimited p.167', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'The character has a superior tactile sense. He can easily recognize very slight differences in textures by touch. Bonuses: Adds + 10% to skills that require a delicate, light touch. For example: Demolitions, pick pocket, pick locks, palming, etc.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Mental Stun', 'minor', 'import', 'Revised Heroes Unlimited p.167', 'heroes-unlimited', '60ft (18.3m)', '2 melees', 'Special', NULL, 'Attacks Per Melee: Equal to half the number of hand to hand attacks. Each mental attack counts. as one attack. 167 Bonuses: None vs psionics can be applied. A power that attacks the balance mechanism of the brain. Victims feel light-headed, dizzy and out of sync. Effects: Lose one attack per melee. - 3 to strike. - 3 to parry and dodge. - 6 to roll with punch, fall or impact. Note: Each attack can only be directed at one person at a time, not an entire crowd at once.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Impervious to Fire & Heat', 'minor', 'import', 'Revised Heroes Unlimited p.167', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'This power makes the character totally impervious to fire, including magical fire, and heat. No damage. a');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Radar', 'minor', 'import', 'Revised Heroes Unlimited p.167', 'heroes-unlimited', '400ft+ 100ft per level of experience.', NULL, NULL, NULL, 'The radar super ability sends out high-frequency radio waves which bounce off objects, returning and indicating the direction and distance of the reflecting objects. This power provides the super being with a crude type of see in the dark ability, enabling him to know/sense the location of objects and movements. Abilities Include: Interpreting Shapes: 50% + 8% per level of experience. Estimating Distance; 60% + 8% per level of experience. Estimating Direction: 60% + 8% per level of experience. Estimating Speed: 40% + 8% per level of experience @ Estimating exact location: 40% + 8% per level of experience. Bonuses: +4 on initiative. +2 to parry/dodge. +3 to strike, One additional attack per melee. No minuses apply when blinded or in darkness. Note: Radar does not go through cloth, wood or people. Consequently, the character can not sec or sense through walls or doors. Likewise, while he may sense a car, estimate its speed, direction and distance, he can not tell how many people are in the vehicle. This ability is especially useful in the dark, long distances, and combat (providing relatively full view of the combat area). Disadvantages: Radar is totally fouled in the rain, snow, dust or sandstorms, and by similar multiple, obscuring, images. NO BONUSES apply under these conditions, including no additional attacks per melee. If these conditions exist at night/dark or while blinded the radar is ineffective and the character is blind and suffers with all the minuses that usually apply. Smoke also fouls radar, but not as severely as the aforementioned conditions. All the abilities to estimate speed, direction, distance, shape and location are - 30%. All bonuses are reduced by half.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Super Vision: Ultraviolet & Infrared', 'minor', 'import', 'Revised Heroes Unlimited p.167', 'heroes-unlimited', 'Equal to normal vision; nightvision is limited to about 300ft (183m).', NULL, NULL, NULL, 'This power enables the character to see in the infrared and ultraviolet spectrum of light radiation. Both types of light are clearly visible to this person. Infrared also provides a limited type of nightvision allowing the character to see clearly in the dark.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Super Vision: Nightvision', 'minor', 'import', 'Revised Heroes Unlimited p.168', 'heroes-unlimited', 'Equal to normal vision.', NULL, NULL, NULL, 'The ability to see clearly in darkness. This includes total darkness.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Super Vision: Advanced Sight', 'minor', 'import', 'Revised Heroes Unlimited p.168', 'heroes-unlimited', 'Two miles, plus one for every level of experience beyond level two.', NULL, NULL, NULL, 'This is a power that gives the character super sharp, crystal clear vision. Distancing vision is not unlike an eagle''s. Although not telescopic, the vision is so sharp that the person can read a small sign or recognize a face/costume up to two miles away.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Super Vision: X-Ray', 'minor', 'import', 'Revised Heroes Unlimited p.168', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'A power that enables the character to see through most substances. Lead and lead alloys will block x-ray vision. It requires a few moments of concentration to see through various substances. Abilities: @ See through fabric or paper up to four inches thick instantly. See through up to one foot (.3m) of wood, plaster, fabric, paper, vegetation; requires one melee (15 seconds) per each foot of material. See through six inches of brick, stone, concrete or metal; requires two melees (30 seconds) per each six inches.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Underwater', 'minor', 'import', 'Revised Heroes Unlimited p.168', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'This power enables the super being to function with incredible prowess underwater. Like a fish he can breathe underwater, swim, and so on. Abilities Include: Breathe Underwater Swim with Amazing Skill Extraordinary Strength Extraordinary Speed Breathe Underwater enables the character to breathe underwater as casily as he does on the surface. Only the super being possesses this power. Swimming abilities are automatic, enabling the character to swim with the skill proficiency of a competitive swimmer. ALL basic swimming techniques and styles are known; skill level - 89%. Extraordinary Strength: The character possesses incredible strength while underwater, The physical strength is increased to P.S. 24; if the character already has a natural P.S. of 20, or higher, add 4 to the P.S. The extra strength applies ONLY when submerged in water. On dry land the super being''s strength is his normal, natural physical strength. S.D.C. also increases underwater; add 100 S.D.C. points. On dry land the S.D.C. reverts to normal. Extraordinary Speed: The character''s speed attribute is tripled while underwater and applies to swimming. +2 to strike. +4 to parry. +6 to dodge. Bonuses Underwater: 168 Add one extra attack per melee. Bonuses on Dry Land: +1 to strike. Add 40 points to S.D.C. (Remember, the 100 S.D.C. bonus underwater no longer applies. Note: This character can breathe and function on dry land like a normal person and for an indefinite period of time; i.c., days, months, years. However, this character feels most at ease, as well as most powerful, in water, i.e. rivers, lakes, seas, and oceans. MAJOR SUPER ABILITY DESCRIPTIONS LIST OF MAJOR SUPER ABILITIES Alter Physical Structure: Electricity Alter Physical Structure: Fire Alter Physical Structure: Ice Alter Physical Structure: Liquid Alter Physical Structure: Metal Alter Physical Structure: Stone Animal Abilities Animal Metamorphosis Chameleon Control Elemental Force: Air Control] Elemental Force: Earth Control Elemental Force: Fire Control Elemental Force: Water Control Others Create Force Field Darkness Control Disruptive Touch Energy Absorption Gravity Manipulation Growth Intangibility Invisibility Invulnerability Karmic Power Magnetism Mechano-Link Mimic Plant Control Shape Change Shrink Sonic Power Sonic Flight Sonic Speed (running) Stretching (elasticity) Teleport Transferal/Possession Vibration Weight Manipulation 169');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Alter Physical Structure: Electricity', 'major', 'import', 'Revised Heroes Unlimited p.169', 'heroes-unlimited', '100ft(30.5m) + 10ft (3m) per level of experience.', 'Instant', '1D6x10 .', NULL, 'An incredible transformation into a living electrical conduit, as well as the ability to manipulate and control aspects of electricity. 1. Fire Electrical Ray Attacks Per Melee: Equal to the hero''s total hand to hand. Bonus: + 2 to strike. A line of electricity emitted from the fingers or eyes. This is the character''s most powerful blast. 2. Mini-Lightning Bolt Range: 100ft (30.5m) + 10ft (3m) per level of experience. Damage: 2D6 ; = Duration: Instant Attacks Per Melee: Equal to the hero''s total hand to hand. Bonus: +3 to strike. : " The discharge of a small electrical energy bolt. 3. Lightning Bolt Range: 300ft(91.5m) + 10ft (3m) per level of experience. Damage: 4D6 Duration: Instant Attacks Per Melee: Equal to the hero''s total hand to hand. Bonus: +3 to strike. This is the character''s second most powerful blast and has the longest possible range. A line of electricity emitted from the fingers or eyes. 4. Electric Flight Range: One mile. Damage: None Duration: One melee (15 seconds) Attacks Per Melee: Counts as two actions/attacks. Bonus: +1 to strike. The individual can transform into a bolt of living energy and rocket himself short distances. Maximum distance: One mile (1.6km); speed: 300mph (482kmph). A full speed body block, or ram, at this speed does 1D4x 10 damage. The electrical field prevents the person from taking damage himself. Note: The rate of travel can NOT be easily regulated; thus the slowest speed possible is 200mph (321kmph). 5. Generate Electricity Self and 4ft (1.2m) radius per level of experience. 1D6 to everyone in the electrical field. Duration: 2 melees (30 seconds) Attacks Per Melee: Counts as four actions/attacks. The character can generate a field of electrical energy around himself (anyone who touches him takes 1D6 damage) or an area of four feet (per level of experience) around him. In the latter case, anybody caught in the electrical field suffers 1D6 damage four times per melee. The attack can last two full melees and counts as four attacks per melee. Range: Damage: 6. Other Abilities and Bonuses: Impervious to electrical attacks (do no damage). Fire and Energy attacks do half damage. Add 40 to S.D.C.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Alter Physical Structure: Fire', 'major', 'import', 'Revised Heroes Unlimited p.170', 'heroes-unlimited', '10ft (3m) + 6ft (1.8m) per each level of experience.', '2 melees per level of experience.', '1D6 or 2D6, plus 1D6 per each level of experi- ence.', NULL, 'The ability to transform into a being of living fire, as well as manipulate and control aspects of fire. i. Continuous Bolt of Flame Attacks Per Melee: Counts as four attacks per melee. Bonus: +4 to strike. The character can shoot forth a bolt or tongue of flame from his hands or finger tips much like a flame thrower. The flame can be continually maintained through concentration until mentally extinguished by the super being. The degree of control is so exact that the character can ignite one finger and use the flame like an acetylene torch, regulating the flames length and intensity. The amount of damage can be regulated to do as little as 1D6 or full power 2D6 + 1D6 per each level of experience. That means a third level character could inflict up to 5D6 damage. The widest the bolt of fire can get is if both hands are used with fingers spread apart, cutting a flaming swath about two feet wide. Damage is the same whether one or two hands are used. Fire Ball Range: 300ft (91.5m) + 10ft (3m) per each level of experi- 170 ence. Damage: 3D6+1D6 per each level of experience. Duration: Instant Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. Bonus: +3 to strike. The super being can create and hurl a ball of flame that dissipates upon impact. The size of the fire ball and amount of damage it inflicts can be regulated by the characters. Minimum damage is 3D6; maximum is the 3D6 plus 1D6 for every level of experience. Create a Wall or Circle of Flame Range: 100ft (30.5m) + 10ft (3m) per each level of experience. Damage: 4D6 points to anybody who passes through the flame. Duration: 6 melees per level of experience. Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. Bonus: +4 to hit a specific area. In this situation the super powered being is able to create a wall or circle of flame to trap others or to block passages. The walls of flame are 6ft deep, up to 24ft tall, and can circle as much as a 20ft radius. Radiate Heat Range: 15ft (4.6m)+5ft (1.5m) per each level of experience. Damage: Special Duration: As long as the character concentrates. No other attacks are possible when the super being is radiating heat. Attacks Per Melee: Counts as two attacks per melee. The character must Concentrate to maintain and increase the heat; counts as two attacks per melee. The super being can radiate heat, increasing the temperature by 50 degrees Fahrenheit (11C) every melee. Thus, within a few minutes the character can generate heat so stifling that even entering the area causes pain and discomfort to normal people. Example: 140 degrees fahrenheit causes discomfort, shortness of breath and intense perspiration. People within the heat radius are likely to pass out. Roll percentile dice: 50% likelihood; roll for every eight minutes of exposure. 200 degrees Fahrenheit causes extreme discomfort, blurs vision, great difficulty in breathing, and 1D4 points of damage for every one minute of exposure. 70% chance of passing out after every 6 melees. Victims of the heat are - 2 to strike, parry, and dodge. 300 to 400 degrees Fahrenheit causes increased discomfort, greatly obscured vision (can barely open eyes), extreme difficulty in breathing and /-6 points of damage for every 2 melees of exposure to the heat. 80% chance of people passing out after every one minute of exposure; - 5 to strike, parry and dodge. 500 degrees Fahrenheit causes immediate pain, blinds while in area (can not open eyes), severely labored breathing, and does 2D6 points of damage every minute. 80% chance of people within the area passing out every other melee. Victims are - 8 to strike, parry and dodge. 700 degrees Fahrenheit creates unbearable pain, completely blinds while in the area, can not breathe, causes 3D6 points of damage every melee. Victims are - 10 to strike, parry, and dodge. 86% chance of passing out every melee. Combustible material will be set ablaze within two melees. 5. Super Nova Range: Self and surrounding area. Damage: Special Duration: One melee. Attacks Per Melee: One Bonus: Automatically hits everything in the blast radius. The Super Nova is a last ditch ability, born in desperation, in which the hero can overheat and literally explode. The experience is usually fatal to the exploding super being. The Explosion Does: 10,000 points of damage to a 100ft radius from the center of the explosion. 5000 points of damage for the following 100ft radius. @ 1000 points of damage for the next 100ft. 500 points of damage for the next 200ft. @ 100 points of damage for the remaining 200ft. Total Blast Radius - 700ft. Note: The super nova requires eight melees of concentration and is irreversible after five melees. Roll on the following survival table: 1-10 Character lives, no permanent damage; unable to use power for 1D4 weeks. 11-25 Character survives, but permanently loses super abilities. 26-86 Character is atomized. 87-00 Character survives, but the character''s power mutates into a completely new power; roll on the random ability table. Also roll on the insanity table: Neurosis and Phobia. 6. Other Abilities & Bonuses: @ Natural Armor Rating when in flame form; A.R.: 14. The flame creates a natural protective barrier that melts many objects before they can strike the blazing hero. Attackers rolling to strike must roll above 14 to hit and do damage (S.D.C. or hit point). Any rolls of 14 or under never reach the target being burned or melted away. This applies only to solid objects such as bullets, knives, rocks, etc. Energy, psionics, explosions and cold attacks are not affected by the flames A.R., but pass right through, doing full damage. @ The natural protection extends to attacks by normal human beings. Unless protected in some way, attackers will take 4D6 damage each time the person strikes the blazing hero. Impervious to fire and heat (does no damage). Note that electricity, lasers and energy all do full damage. @ Flight is a possibility while in flame form. The player can roll to determine whether or not his/her character can fly: 1-50: Can fly; 51-00: Can not fly. The player can roll again to see if flight abilities have developed at third, sixth, ninth, and twelfth levels. If flight is possible, the character can hover and propel himself at a speed of SOmph; + 2 to dodge in flight. Dangerous Limitations: Turning to flame makes walking and touching normal surroundings, let alone lobbing fire balls, extremely dangerous. There is always the threat of setting objects, buildings, and the area ablaze when touched by the flame. The following table can be used. It indicates the chance of a particular type of material catching fire. 20% - Vehicles 45% - Wood Structures 65% - Warehouses or Abandoned Dwellings (old) 60% - Old, Dry Wood Structures 65% - Dry Grass or Woodlands 70% - Typical Home, Apartment or Office 80% - Flammable Materials or Chemicals 80% - Ignite Explosives Note: The character reverts to normal when rendered unconscious. Intense cold, ice, chemicals, or water may douse the flame, forcing the character to revert to normal. Such attacks have a 40% chance of successfully dousing the flame. System shock prevents the character from using his power for 1D8 melees. Cold type attacks also do FULL damage to the fiery character.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Alter Physical Structure: Ice', 'major', 'import', 'Revised Heroes Unlimited p.171', 'heroes-unlimited', '100ft (30.5m)+ 10ft per level of experience.', 'Until it melts.', 'Special', NULL, 'The startling ability to transform into a being of living i ice, as well as manipulate and control aspects of cold. Snow and ice can be created by an extraordinary means of water condensation and freezing of moisture out of thin air. In this way the super being can create snow and ice. 1. Create Snow and/or Ice Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. Bonus: +4 to strike. Note: This attack can be dodged. The character can create a blob of snow or chunk of ice out of thin air, dropping it on top of somebody, or something, or covering an object. The super being can create up to 501bs (22kg) of snow or ice mg Add 5lbs for each level of experience. Dropping a snow sii on top of somebody has the following effects: Damage: 1D4, plus it staggers and momentarily blinds the person; victim loses his/her next attack (one). A 50+ pound ice ball does: 2D6 Damage The creation of this snow and ice can be repeated in the same area to block a passage or door, cover an object, impair movement, cause confusion and so on. 2. Create and Hurl Snowballs Range: 80ft (24.4m) Damage: One point; more of an annoyance. Duration: Instant Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. Bonus: +2 to strike. 3. Create and Hurl Ice Balls Range: 100ft (30.5m) Damage: 1D6 each Duration: Instant Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. Bonus: +2 to strike. 4. Create and Hurl Ice Shards 100ft (30.5m) Damage: 2D6 per attack Duration: Instant Attacks Per Melee: Equal to the character''s total hand to Range: hand melee attacks. Bonus: +2 to strike. Can create and hurl three small sharp daggers of ice in a single thrust. (Counts as one attack). Ice Wall or Shield Range: Up to 100ft (30.5m) away. S.D.C. of Ice Wall/Shield: Small, but thick, 5 x 6ft (1.5X 1.8m): 100 S.D.C; medium size up to 10x 8ft (3 X 2.4m): 60 S.D.C.; large size up to 20 x 10ft (6.1 xX 3m): 40 S.D.C. Duration: Until S.D.C. is depleted or it melts. Bonus: +2 as a parrying maneuver; instant creation. Encase in Ice Range: 100ft (30.5m) Damage: Special Duration: Until it is shattered or it melts. Attacks Per Melee: Counts as two attacks/actions. Bonus: +1 to strike. Ice manacles have an A.R. of 6 and an S.D.C. of 30 for each 6 inches of thickness. Encasing hand held weapons in an ice block will always incapacitate both energy and conventional weapons. S.D.C. 20, A.R. 6 and causes 1D6 points of damage. Encasing victims in ice is a debilitating and potentially lethal tactic. Encasing a portion of the human body, such as hands, wrists, ankles, feet, will impair movement until the ice is broken off. Damage to protected/covered skin: One point of damage for every four melees that they are encased. Unprotected, bare skin takes 1D4 points damage every four minutes, accompanied by numbness and discomfort. Subtract damage from victim''s S.D.C. first. Encasing the entire body, excluding the head, in a block of ice will completely immobilize the average human being. The super being can encase his victim in a block of ice that is consistently six inches thick all the way around. That''s about 200lbs of ice. It requires the ice character one full melee to create the block, and an additional 2 melees for every extra six inches of ice. Causes 4D6 points of damage. The ice block has an A.R. of 8 and an S.D.C. of 100 for each six inches of thickness. Victims can escape an ice block only if it is shattered or melted. Extraordinarily strong characters may be able to use their strength against the ice prison. Encasing the head of a person will immediately cut-off the oxygen supply, causing suffocation. Dizziness will occur within two minutes. If only the head is covered, the victim is - 2 to strike, parry and dodge. Within four minutes the victim will be rendered unconscious. Within five minutes the person will lapse into a coma and die within six minutes. Of course, a HERO, that is a good person, would never use this tactic. The super being can dispel the ice at any time, but takes at least two melees to do so. Freezing water is also an ability of this super powered being. He/she is able to freeze 30 gallons of water per each melee. 7. Generate Ice Range: 20ft (6.1m), up to 60ft (18.3m) away. Attacks Per Melee: Counts as one attack/action. 172 Generating ice creates a thin coating of ice which can be made to cover objects, the ground, floors, ceilings, walls, and even animals and people. The coating is one third of an inch thick and can affect an area of 20ft. If the ice is used to coat a person, it does 1D6 points of damage and discomfort, but does not impair movement. The super being can control his power with such proficiency that he can cover everything in his radius or one specific object or person. Coating the ground will impair movement, reducing speed by half. At half speed there is a 50% chance of slipping and falling each time a person moves. At full speed there is an 80% chance of slipping and falling (crashing, if a vehicle). Each time a person falls he loses one attack/action. 8. Other Abilities and Bonuses: 1 Natural Armor Rating when in ice form; A.R.: 14. The ice transformation makes the character semi-invulnerable. Attackers using fisticuffs or conventional weapons must roll a 15 or higher to strike and do damage. Any roll under the armor rating (A.R.) bounces harmlessly off the icy body, doing NO damage to the S.D.C. or hit points. Conventional weapons, like knives and guns, do one-half their normal damage, even when they beat the A.R. of 14. That is how effective a protection the ice can be. Teflon coated bullets automatically penetrate the A.R., doing full damage. This means that unless the character dodges, he will be hit and damaged by the shell, regardless of his natural armor rating. Teflon coated bullets are specially designed to penetrate armor. As always, subtract the damage from the S.D.C. @ Lasers do NO damage, reflecting and bouncing off the reflective surface of the ice. @ Explosives, including grenades, dynamite, nitro, and plastic explosives, all do /2 damage. @ Normal punches (1D4) do No damage. Super powerful punches do 2 damage. Fire, electricity, psionics and other attacks do full damage. @ Impervious to cold (no damage). Add 50 S.D.C. when transformed into ice. @ The character''s normal weight is doubled when transformed into ice.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Alter Physical Structure: Liquid', 'major', 'import', 'Revised Heroes Unlimited p.173', 'heroes-unlimited', '30ft', 'Instant', '2D4', NULL, 'The weird power to transform into a being of living water-like liquid. 1. Water Bolt Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. Bonus: +2 to strike. The character can instantly draw on moisture in the air, or another source of water, and fire a jet/stream-of water at an opponent. The impact is about twice as hard as a normal punch. 2. Water Behemoth Range: Self Duration: 8 melees per level of experience. Attacks Per Melee: Equal to the character''s normal hand to hand abilities. Bonus: +1 to strike \ Penalties: - 1 to dodge, speed is reduced by 30%. The character can draw on an existing body of water (not just air moisture, unless it''s running) to increase his size and mass to 2, 3, 4, or 5 times his normal size. This means a normal, six foot tall (1.8m), 2001b (90kg) man weighs 400lbs when transformed into water (this is normal). Two times his normal size, the character would be 12ft (3.2m), 800lbs (360kg). A punch does 2D6 damage. Add 40 S.D.C. 173 Three times bigger, the water being is 18ft (Sm), 1200lbs (540kg). A punch does 4D6 damage. Add 80 S.D.C. Four times creates a 24ft (6.8m) giant weighing 1600lbs (720kg). A punch does 6D6 damage. Add 120 S.D.C. Five times bigger is a 30ft (9m) giant weighing one ton (900kg). A punch does 6D6+ 12 damage. Add 160 S.D.C. The increased size is difficult to maintain and can only last two minutes (8 melees) per level of the character''s experience. For Example: First level is 2 minutes/8 melees; second level: 4 minutes/16 melees; third level: 6 minutes/24 melees and so on. When the time has elapsed the character will shrink to normal size, shedding all the extra water and flooding the immediate area with as much as 1600 pounds of water. That''s about 228 gallons (907 liters) of water. : 3. Water Merge The character can completely merge into water and can not be seen. In water form the character does not breathe in the conventional sense (the water is oxygenated); thus he can stay in or under the water for an indefinite period of time. Traveling speed in water is one third normal running speed. 4. Manipulate Shape '' The water being can squish, mold and puddle his physical form. This means he can pour himself through the crack under a door, through a keyhole, down a drainpipe, or squeeze through bars, chains, ropes, etc. If there is a crack water can get through, so can the liquid character. 5. Limited Invulnerability Projectile weapons such as bullets, arrows, or thrown objects do no damage, passing right through the water being. Likewise, physical hand to hand punches, kicks, cuts, stabs, clubbing, etc., do no damage. Gases do no damage. Electricity, energy, fire and heat do full damage, as does psionics and most magic. Laser/light energy does half damage. Intense cold that begins to freeze water causes a chemical change that hurts. Explosions will blow the character apart, but he can reform within 2D6 minutes and suffers no damage. 6. Other Abilities and Bonuses @ Add 20 to S.D.C. Weight is doubled. @ The character radiates no heat when in water form; thus he can not be detected or tracked by infrared or heat sen- SOrs.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Alter Physical Structure: Metal', 'major', 'import', 'Revised Heroes Unlimited p.173', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'A power that transforms the character into a living juggernaut of metal. Unlike the previous physically transforming powers, the Metal being has no energy to control or manipulte. Its power lies in brute strength and physical endurance. 1. Natural Armor Rating and Immense Structural Damage Capacity (S.D.C.). When transformed into a creature of metal, the super character is nearly invulnerable. A.R. 17, S.D.C. 800 (S.D.C. applies only when in metal form). This means that an attacker must roll an 18 or higher to strike and inflict damage. Any roll to strike under the armor rating (A.R.) bounces harmlessly off the metal body. Explosions and other area effect, destructive forces and such as fire, heat, energy, do full damage and do not require a roll to strike above the A.R. Why? Because the damage affects everything within its area of destruction. If the metal character is caught within a blast radius, he takes damage. Note: Fire blasts, electricity, laser and energy do full damage only if the A.R.: 17 is penetrated. If the attack to strike is 17 or less, no damage is done. Normal punches, kicks, knives, clubs and similar attacks do no damage unless exceptional strength is used (P.S. of 17 or higher) and then only on rolls of 18 or higher. Gas and psionics have full effect. 2. Increased Mass and Strength. The character''s normal weight is quadrupled when transformed into metal. Thus, a 2001b person would weigh 800lbs. The physical strength is also increased by 3D4 (roll one time to determine how strong the character is whenever he transforms). 3. Other Abilities and Bonuses: @ S.D.C. of metal (800) recovers at three times the normal rate. @ Speed is reduced by half. @ Impervious to cold. @ Unless physically heated (metal holds heat well) the metal form is cool enough to avoid detection by infrared or heat sensors.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Alter Physical Structure: Stone', 'major', 'import', 'Revised Heroes Unlimited p.174', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'Another transformation power that turns the person into living stone. Like the metal transformation, the real power rests in the incredible toughness and strength of the transformed person. 1. Natural Armor Rating and Immense S.D.C. When transformed into a creature of stone, the super being is nearly invulnerable. A.R.: 16, S.D.C. 600 (S.D.C. applies only when in the stone form). This means that an attacker must roll an 17 or higher to strike and inflict damage. Any roll to strike under the armor rating (A.R.) bounces harmlessly off the stone body. Explosions and other area effect, destructive forces ,such as fire, heat, and energy, do full damage and do not require a roll to strike above the A.R. Why? Because the damage affects everything within its area of destruction. If the stone character is caught within a blast radius, he takes damage. Note: Fire blasts, electricity, laser and energy do full damage only if the A.R.: 16 is penetrated. If the attack to strike is 16 or less, no damage is done. Normal punches, kicks, knives, clubs and similar attacks do no damage unless exceptional strength is used (P.S. of 17 or higher), and then only on rolls of 18 or higher. Gas and psionics have full effect. 2. Increased Mass and Strength The character''s normal weight is tripled when transformed into stone. This means a person who weighs 160lbs will weigh 480lbs when stone. Physical strength (P.S.) is also increased when transformed into stone. Roll 2D6 once to determine what that increase is. 174 3. Other Abilities and Bonuses: @ The S.D.C. of the stone recovers at three times the normal rate. @ Impervious to cold. @ The character radiates no heat in stone form, thus is undetectable by infrared and heat sensors. @ Speed is reduced by half.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Animal Abilities', 'major', 'import', 'Revised Heroes Unlimited p.174', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'This power gives humanoid characters the traits, abilities and instincts of a particular type of animal. It does nor actually transform the person into an animal. Which specific type of animal abilities your character may possess can be selected or determined by rolling on the table that follows: Animal Type 1-10 Fish 11-20 Cat; small, domestic 21-30 Bear 31-40 Mustelid 41-50 Canine : 51-60 Cat; big, wild 61-70 Bird 71-80 Nocturnal 81-90 Hooved 91-00 Reptile The character can also control (to a limited degree) any animals that fall into his general type. Actual communication/dialog is impossible, but the character understands the general meanings of grunts, growls, whines, and facial and tail expressions. The animals will look toward the super being as the leader of a pack and will follow his actions. Commands will be limited to stop, go, attack, wait, run, etc. Animal Types and Descriptions: BEAR Physical Traits: Add 50 pounds to the weight; hands are thick, with heavy, short fingers; ears are small. The character is tough, husky and bulky, yet nimble. Abilities and Bonuses: Cold does half damage. Add 2D4 x 10 S.D.C. Add 3D6 to P.S. attribute. Add 3D6 to P.E. attribute. Extraordinary sense of smell allows the character to detect very faint scent traces. Tracking by smell is possible (like a bloodhound) at a 40% + 5% per level of experience. 6. Recognizing a persons scent is also possible, with a 48% effectiveness. 7. Can control 2D4 bears or dogs. BIRD Physical Traits: cular. Abilities and Bonuses: 1. Glide: Same power as the minor super ability. 2. 180 degree arc of vision. It is extremely difficult to sneak up on this character. 3. Extraordinary vision is approximately six times better than * WR WN = Large, round eyes; tends to be thin, but musnormal human''s. That means an 18 inch (.4m) object can be seen clearly, in perfect detail, up to one mile (1.6km) away. 4. +2 on initiative. 5. +1 to parry and dodge. 6. Also possesses an excellent sense of smell, although not super human. 7. Can control 4D4 birds. CANINE Physical Traits: Pointed ears; large, flat nose and small, pointed, canine-like teeth. Abilities and Bonuses: 1. Double speed attribute and add 10 to it. Add 1D4x 10 .D.C. Add 1D6 to P.S. attribute. Add 1D6 to P.E. attribute. Extraordinary sense of smell allows the character to detect very faint scent traces. Tracking by smell, like a bloodhound, is possible at a skill proficiency of 50% +4% per level of experience. 6. Recognizing a person by scent is also possible at a 56% effectiveness. 7. Can control 3D4 dogs. CAT; Small, Domestic Type Physical Traits: Large slanted eyes, and pointed ears. Abilities and Bonuses: 1. Natural climbing skill - 50% + 5% per level of experience. 2. Natural Prowl ability - 70% + 5% per level of experience. 3. Exceptional balance and agility - 60% to maintain balance and walk a tightrope (does not increase with experience). 4. +4 to roll with punch, fall or impact. 5. Superior vision allows the character to see about twice as good as a normal human. Nightvision - 60ft. 6. Add 1D6 to P.P. attribute. 7. Leap up to 6ft straight up or across (1.8m). 8. Can contro] 2D6 domestic cats. CAT; Big, Wild Predators Physical Traits: Large slanted eyes; large, pointed ears and add 30 pounds to the weight (all muscle). . Abilities and Bonuses: 1. Natural climbing skill - 60% + 5% per level of experience. 2. Natural prowl skill - 50% +5% per level of experience. 3. Superior vision allows the character to see about two times better than a normal human. Nightvision - 60ft. Add 1D6x 10 S.D.C. Add 1D6 to the P.S. attribute. Add 2D4 to the P.P. attribute. Extraordinary leaper: 20ft (6.1m) straight up and 4O0ft (12.2m) across/horizontally. Roar that can be heard up to a mile and a half (2km) away. 9. Can control 2D4 cats of any kind. FISH Physical Traits: Small ears, roundish eyes, pale complexion, and slightly webbed fingers and toes. Abilities and Bonuses: 1. Natural swimmer with a 98% skill proficiency. Swim speed is five times normal speed. we Yew 2a eee a 2. Breathe underwater indefinitely. 3. Physical Strength (P.S.) becomes doubled when underwater only. 4. Nightvision - 60ft out of the water; 120ft in the water (18 or 48m). 5. Add 1D4x 10 S.D.C. (applies in-and out of the water). Add 1D4 to P.P. attribute. 7. Can control 4D6 fish of any kind. a HOOFED (horse; and cloven, like deer, antelope, etc.) Physical Traits: Long face; powerful, muscular legs, and pointed ears. Abilities and Bonuses: 1. Speed running is 10mph plus 1D4x 10mph. Maximum speed can be maintained for one hour before rest is needed. 2. Add 1D6x 10 S.D.C. . 3. Add 2D6 to P.E. attribute. 4. Add 2D4 to P.S. attribute. 5. Keen sense of hearing, about double a normal human''s. 6. Leap up to 6ft (1.8m) high and 15ft (4.6m) lengthwise. 7. Kick attack does 2D6 damage (plus P.S. damage bonus). 8. Can control 2D6 of any hoofed animal. MUSTELID Physical Traits: Reduce height by 3D4 inches (do not adjust weight); small eyes; small, furry ears; husky build and clawed fingers. Abilities and Bonuses: 1. Natural climbing skill - 35% + 4% per level of experience. 2. Natural digging ability: This is the ability to dig through dirt, mud or sand. The character''s Physical Strength determines the speed of the digging. Only the character''s body moves through the earth; no tunnel is left behind. Characters with a P.S. of less than 13 move at a rate of 3ft per melee, a P.S. of 13-18 move at a rate of 4ft per melee, P.S. of 19-24 move at a rate of 5ft per melee and a P.S. of 25 or better dig at a rate of 6ft per melee. Note: This process does NOT leave a tunnel. Tunneling is a digging process that leaves a passable tunnel. Tunnels near the surface can be used as pit traps. Tunneling can be done at half the speed of Digging. Excavation means being able to hollow out large, underground chambers. Characters with Excavation can also dig under buildings, roads, and other structures to weaken their foundations. Characters can Excavate about 5 cubic feet per minute. Note: Tunnels and Excavations are not permanent. Gunfire, earthquakes, and traffic vibrations will easily collapse them. Characters can use building materials to make their underground structures more secure. Clawed fingers do 1D8 damage as weapons/punch. Super flexible backbone (this is true about mustelids); +6 to roll with fall, punch or impact. Nightvision - 60ft (18m). Add 1D4 x 10 .D.C. Add 1D6 to P.S. attribute. Can control 1D8 of any type of mustelids. gees OIA => NOCTURNAL ANIMAL Physical Traits: Large, round eyes. Abilities and Bonuses: 1. Extraordinary vision approximately 10 times better than a normal human. This means the character can clearly see an 18 inch item up to two miles away (3.2km). 2. Nightvision - 600ft (183m). 3. Extraordinary sense of smell allows the character to detect very faint scent traces. Tracking by smell is at a skill level of 35% +5% per level of experience. Identify person by scent is a 48% chance. 4. Natural Prowl skill is 65% +5% per level of experience. 5. Add 20 S.D.C. 6. Add 1D4 to P.P. attribute. 7. Can control 1D8 of any type of nocturnal animal. REPTILE Physical Traits: Round eyes, small ears and minimal body hair. Abilities and Bonuses: 1. Double speed attribute. 2. Leap upto 8ft (2.4m) straight up and 15ft lengthwise (4.6m). 3. Natural climbing skill is 80% + 2% per level of experience. Rappelling is included. 4. Exceptional balance: Maintain grip, hold or footing is 70% +2% per level of experience. Walk tightrope is 60% + 2% per level of experience. 5. Add 1D4x10 S.D.C. 6. Add 1D6 to P.P. attribute. 7. Can control up to 6D6 reptiles of any kind.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Animal Metamorphosis', 'major', 'import', 'Revised Heroes Unlimited p.176', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'The character can completely transform into a particular type of animal, such as canine, feline, etc. As an animal, the person gets all the inherent abilities and defenses that animal form may offer, while retaining his own memory, I.Q., S.D.C., hit points and ability to speak. All physical attributes change, up or down, as best fits the animal. The animal metamorphoser can change from humanoid to animal, and back again, at will. Each change counts as an action/attack per melee. To determine the general abilities of a general animal type, use the descriptions provided under the Animal Abilities (under major super ability) that precedes this one. Or use the mutant animal descriptions (no psionics please) found in the Mutant Section. Some basic notes about animals are provided that should enable players to develop a good variety of animals Claws: Retractable Claws: Small cat (lynx, bobcat), damage - 1D6. Big Cats (lion, tiger), damage - 2D6. Claws: Digging (badger, wolverine), damage - 1D8. Miscellaneous (rodent, lizard), damage - 1D4. Birds of Prey, damage - 1D6. Bear, damage - 1D8. Bear, damage - 2D4; Polar Bear - 2D6. Canine, damage - 1D6; Wolf - 2D6. Feline, damage - 1D6; Tiger/Lion - 2D6. Mustelid, damage - 1D4; Badger/Wolverine - 1D6. Herbivores, damage - 1D4 (horse, goat, ape, human). Birds of Prey, Beak, damage - 1D4. Teeth: 176 Antlers: Small Antlers - 1D4. Large Antlers - 2D4. Horns: Small Horns - 1D6. Large Horns - 2D6. Hooves: Small - 1D6 (kick). Large - 2D6 (kick). Speeds: Wild Canine - about 35mph maximum for up to an hour. Small Wildcats - 15mph in spurts of 10 to 20 minutes. Large Wildcats - 30mph in spurts of 10 to 20 minutes. Cheetah - 90mph in 3 to 5 minute spurts. Deer/Antelope - 30mph maximum for up to an hour. Horse - 40mph maximum for up to an hour. Elephant - 25mph for up to an hour long. . Rhinoceros - 35mph in 3 to 8 minute spurts. Alligator - 35mph in 2 minute spurts. Lizards - 10 to 20mph in 2 to 5 minute spurts. Typical Birds - 30mph. , = Birds of Prey - 40mph. To determine which general type of animal the character can transform into, select one or roll on the following table. Animal Metamorphosis Table '' 1-10 Rodent 11-20 Mustelid 21-34 Cat 35-50 Canine 51-60 Bird 61-70 Hoofed 71-80 Bear 81-90 Reptile 91-00 Any and ALL animals.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Chameleon', 'major', 'import', 'Revised Heroes Unlimited p.176', 'heroes-unlimited', NULL, 'Indefinite.', NULL, NULL, 'A truly unique power that allows the person to blend into and adapt to his environment. 1. Chameleon is an ability that enables the person to change color and texture to blend into his environment. A sort of bio-aura surrounds the character so that even his clothes seem to change to adapt to the surrounding area. Movement destroys the effectiveness of the chameleon ability. Chances of being unseen: 90% Undetectable if completely still. 70% Undetectable if moving 2ft per melee or less. 20% Undetectable if moving 6ft per melee Totally ineffective if moving any faster. Adhesion; the ability to stick to surfaces. The power is identical to the minor super ability of adhesion described elsewhere. 3. Hold Breath for up to 10 minutes. 4. Feign Death by lowering one''s body temperature and respiration. This requires five minutes of preparation and meditation. 5. Natural Prowl Skill is 60% + 5% per each additional level of experience.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Control Elemental Force: Air', 'major', 'import', 'Revised Heroes Unlimited p.176', 'heroes-unlimited', '300ft (91.5m)', 'One melee (15 seconds)', 'Special', NULL, 'The power to manipulate and control aspects of air and atmos- 2. pheric conditions. 1. Wind Rush Attacks Per Melee: Each wind rush counts as two attacks that melee. Bonus: +3 to strike The air manipulator can create a short powerful wind gusting to 60mph (96kmph), and can direct it at a specific target or area. The wind is so powerful that it will stagger or knock people down, blow away all objects in its path weighing less than 30 pounds (13.6kg), and break ordinary window glass. Directed at one specific target, the wind is a hard hitting, focused blast that has a 70% likelihood of knocking down a person/items weighing up to 300lbs (135kg). If a wide (20ft maximum) gust of wind, the likelihood of being knocked down is marginally less; 60%. Everyone caught in the wind is staggered (if not sent sprawling), speed is reduced to one quarter normal speed, one attack per melee is lost, and all attempts to attack are - 6 to strike. Items weighing 30lbs (13.6kg) or less will be sent flying 3D6 x 10 feet away. Vehicles or characters weighing over 300lbs have no fear of being knocked over, but speed is still reduced and the penalty of - 6 to strike still applies because of the wind''s force and flying debris. 2. Whirlwind Range: 20ft radius; 300ft distance Duration: 8 melees (15 seconds) The super being can summon winds to create a rotating windstorm of limited intensity. Moving in an inward and upward spiral motion, the 75mph winds will suck, hurl, and dash to the ground anyone or anything within a 20ft (6.1m) area. Anyone caught in the wind can not attack or speak for one melee. They will be snatched up and hurled approximately 20ft, taking 4D6 points of damage. The wind will affect anything weighing less than 700lbs (315kg). Ride the Wind Range: Self Duration: 10 minutes Maximum Speed: 15mph This ability enables the super being to manipulate air currents and wind speed to carry himself and an additional 200lbs aloft. Riding the winds is not the ability to fly, but is, more accurately, the ability to hover, rise above the ground (up to 30ft per melee), and glide. The gliding is very limited and requires the concentration of the air controller. He can still use his other powers while aloft. If he is knocked unconscious or severely hurt (S.D.C. or hit points suddenly reduced by 80%) he loses all control and plummets down to earth. Change Wind Direction Range: 320ft radius Duration: 4 minutes per level of experience. The super being can change the direction of the wind in a small area by manipulating air currents. Stop Wind/Control (wind) Speed Range: 160ft radius Duration: 4 minutes per level of experience. Again, by manipulating wind currents, the super being can completely stop the wind. 177 6. Create Air Bubble Range: Self or 60ft away (1 8m) Duration: 12 minutes This character can create a bubble or pocket of air. This can be done underwater or in a place where there is at least a minute quantity of oxygen. The bubble offers protection from gases, foul odors, etc. Bubble Radius: 6ft; Speed: The bubble can be moved, but at a limited speed factor of 10. 7. Call Lightning Range: 120ft Duration: Instant Damage: .6D6 Savings Throw: As a dodge. Attacks Per Melee: Equal to the character''s s total hand to hand attacks. '' Bonus: +2 to strike. ef The character can call down a lightningbolt to strike a specific target. 8. Atmospheric Manipulation Range: 500ft radius (152.5m) Duration: 15 minutes Attacks Per Melee: Each act of manipulation counts as two attacks per melee. This incredible power enables the air controller to actually alter atmospheric conditions, including the following: 1. Darken sky; heavy overcast; creating a dark, ominous sky. 2. Cause a loud, eerie thunderclap. 3. Increase or decrease the wind speed 5mph per melee, up to a maximum of 60mph. 4. Increase or decrease precipitation 10% per each melee, up to 90%. 5. Dispel a fog at a rate of eight square feet per melee. 6. Create a fog at a rate of eight square feet per melee. The controller can create any one effect per melee, maintain it or combine effects, adding one to another. For Example: He might first darken the sky, increase the wind speed, then create a fog, and throw in a thunderclap or two. Effects such as fog or darken sky will last for 15 minutes, enabling the super being to go about other activities or use other powers. 9. Other Abilities and Bonuses Resistant to cold and electricity (does half damage).');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Control Elemental Force: Earth', 'major', 'import', 'Revised Heroes Unlimited p.177', 'heroes-unlimited', '120 feet', 'Permanent, until knocked down or dispelled by', 'Special', NULL, 'The power to manipulate and control aspects of the earth. To use any of these powers there MUST be a vast source of earth (stone, dirt, clay, sand) within a 600ft radius. The earth is molded and manipulated, not created. 1. Wall of Earth the creator. Attacks Per Melee: Counts as one attack/action. Bonus: +1 to parry. The super being can create a wall that''s 18ft long by 12ft high by 3ft thick. A dirt wall has a S.D.C. of 200 and an A.R. of 10; a stone wall has a .D.C. of 400 and an A.R. of 15, All attacks strike the wall and do full damage to its S.D.C. A roll of 16 or higher (11 or higher for a dirt wall) will go right through the wall. Fortunately, any attacks that penetrate are - 5 to strike anybody behind the wall. The wall can be molded into a circle, dome or straight wall. Note: The wall rises from the ground and DOES NOT magically appear out of thin air, nor above the ground. 2. Tower of Earth Range: 100ft (30.5m) Duration: 4 minutes Attacks Per Melee: [Equal to the character''s total hand to hand melee attacks. This power enables the super being to call forth a great mound of earth or stone that will shoot up, out of the ground, carrying anything under it skyward. Height of the Tower: 12ft per level of the super being. Width at the top of the tower is six square feet per each level of experience. Victims pushed skyward are temporarily knocked off balance, losing two attacks, and are - 5 to strike, parry or dodge for the FIRST MELEE. After that the victim can attack as normal. If the victim falls he will take 1D4 damage per each 12ft. The S.D.C. of the tower is 120 per each six foot area. The tower will disappear back into the earth after four minutes have elapsed. Of course, the super being can maintain or recreate the tower, by force of will, at the end of the four minutes. Hurl Earth Range: 90ft Duration: Instant The character can actually cause chunks of earth to raise up and hurl them at a target. Up to S0lbs can be affected per melee, and can be hurled as one large chunk or several small chunks. Damage: Per 10lbs of dirt or clay - 1D6 damage; 10lbs of rock or stone - 2D6 damage. Chunks smaller than 10lbs do a mere 1D4 damage. 40 or 50lbs does 1D4 x 10 damage. Quicksand Range: 6ft radius Damage: Special Duration: 10 minutes This power enables the person to transform normal earth and stone into a pool of quicksand, up to 20ft deep. Anyone stepping into it will find himself sinking at a rate of two feet per melee. Struggling (movement) doubles the sinking rate. If submerged, the victim will suffocate within 3 minutes (12 melees). Victims can be pulled, flown or levitated out. Attacks from the pool of quicksand are reduced by half and are - 5 to strike, parry and dodge. Rend Earth Range: 140ft (42m) + 40ft per level of experience. Duration: Special Attacks Per Melee: Once, but other attacks can be made within that same melee. The super being can split the earth like a mini-earthquake, creating a 15ft wide, 20ft deep, 40ft long crevice. These are the maximum measurements and can be adjusted to the super 178 , Range: being''s desires. The opening can be made up to 140ft away and can be repeated once every melee and can be linked together to create much longer openings. Falling into the chasm does 2D6 damage. Climbing down takes about 2 melees; climbing up, 4 melees. Duration: The openings in the earth will remain until closed by the super being. This ability also enables the super powered character to create openings in walls (concrete, brick, or plaster; not wood) and buildings. Even after the super being closes the wall there will still be a large crack, and at least minor structural damage, varying with the size of the opening. Sand/Dust Storm 30ft radius; 180ft away Duration: 4 minutes Attacks Per Melee: Once per melee, but other attacks can be made during that same melee. , The dust or sand particles can be manipulated to fill the air in order to create a sand or dust storm. The storm can be created up to 180ft away and affects a 30ft radius. A storm can be whipped up once per melee. Victims are blinded while in the storm, all sense of direction is lost; all attacks, strike, parry and dodge, are - 6. Speed is reduced by half. Encase in Earth ; Range: 120ft Duration: Special Attacks Per Melee: attacks. A very powerful, but controlled, ability in which the super being can cause earth (dirt, clay, sand) or stone (including concrete) to rise from the ground to engulf an object or person. The character has absolute control over the earth and can encase just a foot or leg, or the entire body. Encasing a whole body in a dirt or stone cocoon will not harm the imprisoned person (although hot and uncomfortable) unless the head is encased. Encasing the head will cause suffocation within four minutes; a tactic a good alignment hero would never do. To encase something, the item must be touching the ground! The super being can manipulate 400lbs of dirt or 200lbs of stone per melee. The following is a list of the Equal to the total hand to hand melee . various stages of encasement, their weight and S.D.C. Metrics Note: 10 pounds equal 4.5 kilograms. Encasement Earth Stone Foot/Ankle 30lbs,S.D.C.10 20lbs, S.D.C. 25 Foot/Leg 60lbs,S.D.C.20 40lbs,S.D.C. 40 Lower Body 120lbs,S.D.C.35 90lbs, S.D.C. 60 Whole Body 300lbs,S.D.C.80 200lbs,S.D.C. 160 Hand/Wrist 30lbs,S.D.C.10 15lbs,S.D.C. 25 Hand/Arm $0lbs,S.D.C.15 30lbs, S.D.C. 30 Car Tire (each) 50lbs,S.D.C.15 30lbs,S.D.C. 30 \4 mid-sized car 400lbs, S.D.C. 120 200lbs, S.D.C. 160 Whole mid-sizedcar 800lbs,S.D.C. 240 400lbs, S.D.C. 320 Use this list as a basic guide for encasing other objects and vehicles. Remember, concrete can be used as if it were stone. However, once a sidewalk or wall is ripped up to encase someone it is permanently damaged. The cement (as with earth) can be put back, but will still be cracked, loose, and crumbly. Snaring one''s target: The character must roll to strike his intended target. Encasement works best on stationary targets; +8 to strike. Moving Targets are much more difficult to snare: Walking or slow-moving targets, +1 to strike; fastmoving or running targets, are - 5 to strike. Flying, hovering, or water bound targets can not be affected. Duration: Until the victim or object has broken free, or until the super being releases it. The super being can negate the encasement at any time, which will cause the cocoon to crumble away. Savings Throw: Intended victims get to dodge out of the way, but are - 2 to dodge.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Control Elemental Force: Fire', 'major', 'import', 'Revised Heroes Unlimited p.179', 'heroes-unlimited', '100ft(30.5m)+ 10ft (3m) per level of experience.', 'Instant', '4D6', NULL, 'i. The power to manipulate and control aspects of fire. Fire Blast Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. Bonus: +2 to strike The character can create a fiery bolt or blast out of thin air and hurl it at a target. Spontaneous Combustion Range: 30ft (9.1m) Duration: Instant Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. This ability causes any COMBUSTIBLE material to ignite. Spontaneous combustion does NOT create a blazing fire, but only the spark to start a fire (although a Fuel Flame can quickly change that). Combustible material must be available to burn, whether it be old rags or dry wood. Human body hair should not be considered a combustible material. Fuel Flame Range: 120ft (36.5m) radius, 300ft away (91.5m) Duration: 4 minutes Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. Much like the pyrokinetic power of the same name, fuel flame quadruples the size of an existing flame or ignites a smoldering ember. The fire can be fueled every melee, increasing the flame to four times its previous size. A radius of 120ft can be affected up to 300ft away. Create Flame Wall Range: 60ft (18.3m) Damage: 4D6 Duration: 10 minutes Attacks Per Melee: One per melee, but other types of attacks can also be used during the same melee. The fire controller can not create a fire wall out of thin air, but can control an existing fire (even a small one) to form a wall or circle. He can even make a fire, right at hand, suddenly race 60ft away to form a wall or circle. Anyone passing through a fire wall will receive 4-24 points of damage. This effect can be done once every melee. Note: The wall 179 can only be as large as the fire present; thus, it could be a tiny wall or a mammoth wall depending on the size and strength of the fire. 5. Extinguish Fire Range: 120ft Duration: Permanent (until a new fire is made) This ability permanently extinguishes any fires within a 90ft radius, up to 120ft away. This can be done once every other melee. The fire controller can also bend this power to part or cut a swath through fire (10ft wide and 320ft long). 6. Create Smoke Range: 90ft Duration: 4 minutes The character is able to generate a dense, grey-black cloud of smoke. The cloud can be created from fiery material that''s up to 90ft away. The cloud is 30 x 30x 36ft, temporarily impairing the vision of everyone caught in it. Victims can not see beyond the smoky cloud and are - 6 to strike, parry and dodge. 7. Invulnerability to Fire '' Range: Self only The character is impervious to ALL types of fire and heat. No damage.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Control Elemental Force: Water', 'major', 'import', 'Revised Heroes Unlimited p.179', 'heroes-unlimited', '120ft radius, up to 600ft away (183m)', '12 minutes', '2D6', NULL, 'The power to manipulate and control aspects of water. To use any of these powers there MUST be a source of water within a 600ft radius. Without an ample source of water the super being can not use any of the powers. Water source can be a sewer, water pipe line, pond, lake, ocean, or even rain. 1. Calm Water Attacks Per Melee: One; takes the place of all other attacks. The ability to impose one''s will over the forces of nature, reducing the intensity of water turbulence. The size of waves, their speed and potential damage are reduced by half. The calming effect can be repeated in the same radius only after the initial effect lapses or is cancelled. 2. Create Waves Range: 240ft (73m) Duration: Instant Attacks Per Melee: Counts as two attacks. Bonus: +4 to strike The character is able to manipulate large sources of water to create a variety of waves in water or on land. The size and speed of the waves can be controlled by the character with the following effects: Small Wave: 2-8 feet tall, 12ft long, does 1D6 damage to all objects and people struck. Large Wave: 10 to 20 feet tall, 24ft long plus 10ft per level of experience. Damage: 4D6. Affects everything hit by the wave. Huge Wave: 24 to 36ft tall and up to 60ft long. Damage: 1D4 x 10. Note: Huge waves have a 84% chance of capsizing small vessels, 60% chance to capsize medium vessels, and a 40% chance of capsizing large (liners, ships) vessels, but only when the character is fifth level or higher. Opponents who are hit by the wave, on land or deck top, are likely to be knocked down and carried 2D4 x 10 feet away. The likelihood of this is: Small wave - 60%, for items 500lbs and under. Large wave - 70%, for items 1000lbs and under. Huge wave - 80%, for items 4000lbs and under. If a person is washed away by the wave he loses three attacks that melee. If hit by a wave, but not washed away, the person loses one attack (momentarily blinded). Water Slam Range: 140ft (42.7m) Duration: | a melee Attacks Per Melee: Counts as two attacks. Bonus: +3 to strike. Water Slam is a comparatively smaller, but powerful, wave that rises up like a hand and slams down on one specific target. The water slam towers to about 16ft tall and 6ft wide. It can also be used on land if sufficient water is available; 200 gallons or more. (Designer''s note: Yes, I realize that the range, damage, and size are different than the psionic water slam. That''s because, while similar, the two water slams are different). Victims of a slam lose an attack, as well as take damage. Water Spout Range: 90ft (27.4m) Duration: 1 melee Attacks Per Melee: Counts as one attack. This is the tricky technique of summoning up a spout-like wave. This will push its victim skyward, bouncing atop the water spout. A large body of water must be available. Height of Spout: 12ft per level of experience. Weight Limit: 6001bs per level of experience. Being dropped from a spout into water does 1D4 damage per every 20ft of height; dropped on the ground does 1D6 per each 12ft of height. Victims are - 6 to strike, parry and dodge while atop the spout. Note: A spout or tower of snow can be made if the conditions are right; sufficient snow MUST be present. Victims are - 2 to strike, parry, and dodge atop the snow tower (which is much more stable than flowing water). All other conditions are the same as the water spout. Wall of Water Range: 160ft (48.7m) Duration: 6 minutes Attacks Per Melee: Counts as one attack. This will call up a wave which will suspend itself to create a wall. The wall can be up to 6ft thick, 30ft tall and 30ft long. It will slow and deflect bullets and lasers, making them - 8 to strike. Fire type attacks that pass through do / damage. It requires 2 melees to push through the wall or one melee on a vehicle at equivalent speed. The water can be molded to the shape of a wall, circle or dome. Because of the vast amount of water it is impossible to see beyond the wall. This ability requires a vast amount of water, like a very large swimming pool, lake, river, etc. 180 Note: A snow wall can also be erected if there is a sufficient amount handy. The wall is not packed snow and is a somewhat less effective shield. It can be up to 3ft thick, 18ft tall, 20ft long. Bullets and lasers are - 6 to strike (mainly because targets can not be seen through the wall). Fire bolts passing through do half damage. It takes one melee to plow through by hand; half a melee with a vehicle or plow. Whirlpool Range: 340ft away Duration: 8 minutes Attacks Per Melee: One; no other attacks are possible. This ability creates a huge, spinning whirlpool in any large body of water (lake, river, sea, etc.). This watery funnel pulls and sucks all objects in or on the water into its whirling center, crushing and dragging them down into the depths. Objects caught in the outer edge will be snagged in the pull and drawn toward its center in a spiraling circle, at a rate of ten feet per every two melees. Victims in the water will become dizzy and disoriented, with a 28% chance of drowning. Victims can be pulled, flown or levitated to safety. Boats and ships may be able to pull themselves away; 66% chance of boats pulling free - roll once each melee. The whirlpool affects a 30ft radius and does 4D6 points of damage to everything in its grip every melee. The creator of the whirlpool can cancel it at any time and can create one every minute/4 melees. Create an Air Bubble (underwater only) Range: Self or 140ft (42.7m) away. Duration: 6 minutes per level of experience. The hero can create an air bubble underwater, affecting a maximum radius of eight feet. The bubble can be created around oneself or up to 140ft away. The bubble can not be moved easily; normally floating along with the tide with a slight, upward drift. Through intense concentration the person who created the bubble can direct it, moving at a speed factor of 6. Controlling the bubble consumes most of the person''s concentration, preventing him from using any other power unless he stops the bubble. The bubble can be punctured and destroyed by any type of attack. Bubble S.D.C.: 50. The super being can create ONE bubble per melee, but can not move more than one per every three levels of experience. Walk on Water Range: Self or others within a 4ft radius. Duration: 10 minutes Attacks Per Melee: Counts as one attack/action; other attacks during that same melee are possible. This is exactly what it sounds like; the person is able to stand, walk, run or float atop water (including a water spout or wave), but speed is reduced by half.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Control Others', 'major', 'import', 'Revised Heroes Unlimited p.181', 'heroes-unlimited', '12ft+5ft per level of experience.', '4 minutes (may be repeated)', NULL, NULL, 'This power affects any intelligent creature, or animals. It can temporarily bend the will of its victim so that they are under the complete control of the super being. The affected person will do absolutely anything the controller requests. All questions will be answered truthfully and in as much detail as requested. However, the controlled person will answer and obey ONLY the person controlling him/her. ALL victims of control are minus one to strike, parry and dodge because of the disorienting influence of being controlled. Victims will remember their actions after being controlled. Limitations and Restrictions: The control (others) power has a few limitations: 1. The character possessing the control power must see or be aware of the person(s) in order to control him/her. 2. Eye contact is an important factor; without eye contact the success ratio drops considerably. This means intended victims, hiding behind him, behind a locked door, or in another room, are all +6 to save vs control because there is no eye contact. When eye contact is made, the intended victims have no automatic bonus other than a possible psionic, magic or M.E. bonus. 3. Savings throws are the same as the psionic''s (even though this IS NOT a psionic power). Non-Psionics must roll a 15 or higher to save; 181 Psionics must roll a 10 or higher to save; Animals have little chance of saving against this attack, and must have a roll of 17 or higher to save. 4, Attacks per melee: One control can be attempted per each melee round (15 seconds). However, this counts as an EXTRA attack in addition to any physical attacks/combat training the character may have. This means that if a character has three hand to hand attacks per melee, he can strike three times plus one mind control attack. 5. Controlling several people at a time is possible, but takes its toll on the controller. There is no exact limit as to how many individuals can be controlled, but the greater the number, the more difficult it is to maintain control on each. Thus, for every four people controlled, the group of them is +2 to break free (or save) from their mental bonds. Each victim of control gets to roll a save vs control every two minutes/8 melees when in a group (2.or more). Note: This bonus to save vs control applies ''only to groups of people controlled simultaneously, and not individuals. 6. Individual control (that is, the controlling of one person) is considerably stronger than a group control. Consequently, an individual who has missed his first savings throw is completely controlled for the full duration of four minutes. If the controller tries to maintain control for another 4 minutes, the victim gets to roll vs mind control. If the controlled person is commanded to take his own life or the life of a loved one, the character gets an automatic savings throw to break free of the controlling influence at +8 to save. Likewise, if a person is commanded to do something that is extremely contrary to his or her beliefs or ideals, that person gets an automatic savings throw to break free; +3 to save. 7. Controlling animals is fairly simple; it requires eye contract and they must be within range. The character with the contro] power can control up to four animals without any problem. Five or more and the group resistance factor arises (same as people; see point #5). Power Bonus: Characters with the control power are +6 to save against control (others) or any psionic mind control, such as mind bond, mind wipe, hypnosis, telepathy and mind control (psionic). Bio-manipulation, empathy and empathic transfer are not mind control attacks and, as such, the bonus of +6 does not apply. This bonus is in addition to any possible M.E. attribute bonuses. Characters with this power also get a M.A. attribute bonus of +2-8 (roll 2D4 and add the roll to the M.A.). Note: Heroes of a good alignment, principled, scrupulous, and even unprincipled, will never intentionally cause an innocent person to commit a crime or jeopardize their life. Nor will they usually use their power to blackmail people or for their own personal gain.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Create Force Field', 'major', 'import', 'Revised Heroes Unlimited p.181', 'heroes-unlimited', 'Self or 40ft (12.2m) per level of experience.', '1 hour, or until destroyed or cancelled by the field''s creator.', '2D6', NULL, 'Attacks Per Melee: Equal to the character''s hand to hand melee attacks; as long as the force fields created do not exceed the S.D.C. maximum. Bonus: +2 to use as a parry. 1. Create a Force Field This formidable power enables the character to generate an invisible or semitransparent field of energy/force. The force field can be mentally shaped as a wall, circle, dome, box or bubble. Maximum size is approximately a 40 square foot area, plus 10ft per level of experience. Maximum S.D.C., possible is the character''s P.E. attribute number times 100. This means a character with a P.E. of 9 can create a force field of up to 900 S.D.C. strong. Multiple Force Fields can be created as long as their combined total S.D.C. does not exceed the maximum possible S.D.C. For Example: A character with a P.E. of 9 has up to 900 S.D.C. (P.E. 9x 100) that he can use to build force fields. The total S.D.C. can be put into one powerful force field or divided up to create several smaller or less powerful force fields. If the character created one force field with 300 S.D.C. and three others with 200 .D.C. each, he has reached the total maximum S.D.C. of 900. No other force fields could be created, unless he dispels one of the preexisting force fields and uses those .D.C. to create another. The force field''s loss of .D.C. affects the creation of other force fields because it temporarily drains the super character. However, he regains force field S.D.C. at a rate of 200 an hour or 3 per minute. 2. Body Armor The character can create a light force field that follows the contours of his body to create a sort of invisible body armor. Limitations: Maximum S.D.C. is 200. Constant concentration to maintain the flexible body shield means the character loses one attack per melee and is - 2 on initiative. Speed and movement are not impaired. Gases are still effective (only the bubble closes out gases). Bolts of Force Range: 40ft (12.2m) + 10ft (3m) per level of experience. Duration: Instant Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. Bonus: +2 to strike S.D.C. Cost: 5 each bolt The character can create small, nearly invisible, bolts of force which can be fired at an opponent. Because they are barely visible, opponents are minus - 4 to parry and dodge force bolts.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Darkness Control', 'major', 'import', 'Revised Heroes Unlimited p.182', 'heroes-unlimited', '140ft (42.7m) Area of Affect: Up to a 40ft area (12.2m) + 10ft (3m) per each additional level of experience.', '5 minutes or until the character dispels it.', NULL, NULL, 'A power that allows the character to create and manipulate darkness. 1. Create Darkness The character can create an area of total darkness up to 140ft away. The darkness is so black that normal vision, nightvision and light amplification optic systems are ineffective. Those trapped in the darkness are blind and - 8 to strike, 182 parry and dodge. The firing of weapons and energy blasts is equal to shooting wild and likely to hit an innocent bystander or comrade. Note: Infrared optics, heat sensors and exceptional hearing can be effective in this darkness. The creator of the darkness can expand, contract and move the darkness (speed 6) at will. Creating darkness counts as one attack/action per melee. Other actions during the same melee are possible. . 2. Shadow Meld The ability to become invisible in shadows or darkness. The only requirement is that the shadow or area of darkness must be man-sized. Exposure to light will dispel the darkness/ shadow and reveal the character. Nightvision Range: - 600ft (183m) in normal darkness; 30ft 0. lm) in his own, unnatural, darkness. :');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Disruptive Touch', 'major', 'import', 'Revised Heroes Unlimited p.182', 'heroes-unlimited', 'Touch', 'Special', 'Special', NULL, 'Attacks Per Melee: Equal to the character s total hand to hand melee attacks. This lethal power actually disrupts the nervous system of the person who falls victim to it. The touch can cause the following effects: Disrupt Optic Nerves temporarily blinds the person; victims are - 9 to strike, parry and dodge. Disrupt Nervous System immobilizes the motor part of the brain causing temporary paralysis. Victims are completely incapacitated. The duration of the blindness and paralysis is 3D4 minutes; Savings Throw: 15 or higher. The disrupt nervous system ability can also inflict Pain doing 3D6 damage (first to S.D.C. and then hit points). The Death Touch is by far the most dangerous of the disrupter touches. The touch causes 6D6 damage and shocks the nervous system, plunging the victim into a coma unless a successful savings throw of 15 or higher is made. If the savings throw is successful, the person only suffers physical damage and is NOT placed in a coma. Those who fall into a coma are subject to the normal surviving coma/death rules. Side effects from physical damage are not applicable. Those who fail to save vs coma/death die. Coma Savings Bonus: Because this is an unnatural effect, the victim''s body is slightly more resilient, providing a bonus of +10% to save vs coma/death. The use of the Death Touch also takes its toll on the person inflicting the coma. The super being himself is drained each time he uses the Death Touch (the other disruption touches do no damage). Side effects from using the Death Touch: Reduce speed by half, - 2 to strike, parry, dodge, and - 2 for ALL savings throws for 2D6 melees. Side effects from multiple or continuous use of the Death Touch are cumulative. Note: The super being possessing the disrupter touch must physically touch his opponent to have any effect. The touch will induce its effects on bare skin and through all normal fabrics; but will not effect those in robots, exo-skeletons, environmental body armor, or transformed into an inorganic substance. Other Abilities and Bonuses: @ Impervious to his own touch. Add 1D6 to P.E. attribute. @ Add 1D6x 10 to S.D.C. @ +10 to save vs coma/death. Poisons, toxins and drugs have only half their usual effects, damage and duration.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Energy Absorption', 'major', 'import', 'Revised Heroes Unlimited p.183', 'heroes-unlimited', '(ft per level of experience.', 'Instant', '2D6 ae', NULL, 'This character is a sort of living energy sponge that can soak up, store, and harmlessly convert and release energy. This means the character is impervious to heat, fire, laser blasts, electricity and other forms of energy. The only exception is kinetic energy, meaning punches, kicks, thrown weapons, bullets, explosions and so on, which will do full damage. 1. Draining Touch The character can drain the energy out of an item, like a car battery or energy pack, by touching it. Maximum absorbtion capacity is one gigawatt per level of experience, That''s the rough equivalent of 10,000 car batteries. 2. Energy Discharge The character can touch an electrical/energy conductor and send a power surge into the system, at least temporarily shortcircuiting the system, if not frying it completely. Maximum discharge is 10,000 watts per level of experience. ~ 3. Energy Flash 2 Attacks Per Melee: Once per melee, but other attacks can be made during the same melee. The character can discharge a sudden energy flash that will strike everyone within the area of the discharge. Unfortunately, the character can not control or direct the energy to strike a specific target. 4. Glow Range: Self The storage of energy can be released as light. This character can glow with up to 500 watts of light. The light can be restricted to a specific part of the body, like a hand or arm, or the entire body. 5. Shoot Light Beam Range: 2000ft (600m) Damage: None Duration: Instant or indefinitely Attacks Per Melee: Equal to the character''s hand to hand melee attacks. The light beam is completely harmless in that it does no damage. However, it is so bright that it can be used to temporarily blind an opponent (for 1D4 melees) if shot into the eyes. Blinded opponents are - 6 to strike, parry and dodge. The beams can also be used as a beacon or searchlight. Maximum width of the beam is two feet if both hands are put together with fingers spread wide. 6. Other Abilities and Bonuses: Add 1D6x 10 to S.D.C. @ Add 1D4 to P.E. attribute. 183');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Gravity Manipulation', 'major', 'import', 'Revised Heroes Unlimited p.183', 'heroes-unlimited', 'Self or item/person up to 140ft (42.7m) away. Area Affected: Self, others, or 20ft radius.', 'Indefinite The super being can reduce gravity to a fraction, with the following results: The affected person, whether it is oneself or others, can: Carry up to 100 times his normal weight capacity. Leap two feet for each P.S. attribute point. Example: P.S. of 10x 2=20ft. That''s up or lengthwise. Speed is tripled. +3 to dodge. :', NULL, NULL, 'The control and manipulation of gravity. 1. Reduce Gravity Throw objects (even huge, heavy objects) great distances. If the object can be lifted overhead it can be thrown a distance of 400ft. Reduce the distance by SOft (16.2m) for every 1000lbs. Remember, this effect can be placed on oneself, or others within the 120ft range, or on an area (20ft radius) up to 120ft away. Duration: The effects will last as long as the gravity controller maintains his concentration. Fortunately, only minimal concentration is required, enabling him to engage in combat or other actions. However, he can not use any other gravity power. 2. Increase Gravity Range: 140ft (42.7m) away. Area Affected: Self, or other object or 20ft radius. Duration: Indefinite This ability is the opposite of the reduce gravity effect, enabling the super being to create bone crushing gravitational conditions. @ Increase weight up to 50 times the objects or person''s normal weight. Actually, the weight is not altered, but it''s the gravitational pull that makes it seem like it weighs more. Speed is reduced by 5 points per every 200lbs of weight. @ The gravity effect can be concentrated on one individual target (object or person), completely immobilizing him/it. The pull is such that he can not move or be budged. Duration: Same as reduce gravity. 3. Zero Gravity Range: 20ft per level of experience. Area Affected: 6ft radius (1.8m) Duration: 4 minutes The character can create an area with no gravity at all. Anything within the radius, or anything specifically affected, is completely weightless and will float about 10ft above the ground. People caught in zero gravity are - 2 to strike, parry and dodge. Weight Limit: The maximum amount of weight that can be made weightless is 10,000lbs (that''s 5 tons), plus 1000ibs additional per each level of experience. Zero gravity can be made to affect one person, object, or an area. As with the previous two gravity abilities, the effect can be maintained as long as the super being is concentrating to do so. 4. Antigravity Flight Speed: 20mph (32kmph) maximum. Height: 100ft (300m) maximum The character can hover or propel himself through the air.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Growth', 'major', 'import', 'Revised Heroes Unlimited p.184', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'The ability to greatly increase one''s size and mass. 1. Maximum Height: Two feet for every one P.E. attribute point. This means a character with a P.E. of 14 can increase his size by 28 feet. 2. Weight Increases at a rate of 5O0lbs per foot. So 28 additional feet of height also means 1400 pounds of weight. 3. S.D.C. increases at a rate of 20 for each additional foot of height. An extra 28ft means an extra 560 S.D.C. 184 4. Strength increases at a rate of one for each additional foot of height. 28 extra feet means +28 to the P.S. attribute. Remember to adjust strength damage bonuses at each new size. 5. Other Abilities and Bonuses: @ Increase the P.E. attribute to a''minimum of 14. @ The bonuses that follow apply when the character is 20ft or bigger; +2 to strike and parry; Speed is doubled. @ Penalties: - 4 to dodge.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Intangibility', 'major', 'import', 'Revised Heroes Unlimited p.184', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'This power affects the bonding element of molecules, making the person and 20lbs (9kg) of additional material intangible. Intangibility means that sticks and stones, punches, ballets, lasers, and most conventional attacks pass right through; harmless, like a ghost. : However, he is not invulnerable to all attacks. Electricity and sonic blasts, which stimulate and agitate molecules, do half damage. Psionic attacks have full effect. Gas attacks are particularly effective, as the gaseous substance passes right through and into the blood stream, doing full damage/effect. The intangible person can not touch, pick up or carry anything, but can speak and hear as normal. The character can walk through any substance, stone, steel, earth, machines, etc., without affecting it or himself. Although the character can not glide or float, falls or explosions can not harm him. Because of the intangible state, he can sink into the earth/ground up to his nose and walk on the dense molecules, effectively walking through the earth. Likewise, he can actually walk on the dense molecules of smoke and water. Just as the intangible character can not pick up or touch any object or person, he can not engage in combat. Any blows would pass harmlessly through the person. Nor can he partially materialize or materialize a portion of his body. To materialize while partially in an object will result in instant and painful death. The intangible person can not throw an intangible object and expect it to become tangible and strike its target (it doesn''t work that way). To attack, the super being must first become tangible and then attack. Likewise, machines do not function while intangible. The characters can become tangible or intangible nearly at the speed of thought; four times per melee is the maximum. Passing through computers or electrical equipment does not affect or harm the machines. No, intangible people can not walk on air. While intangible, the person seems to be semitransparent, almost spectre-like. He is the perfect spy, being nearly invisible and silent. His appearance alone can be quite harrowing. Other Abilities and Bonuses: @ Add 1D6 to M.A. attribute. @ Add 1D4x10S.D.C. . Add +20% to Prowl ability.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Invisibility', 'major', 'import', 'Revised Heroes Unlimited p.184', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'The super being and anything he is wearing or carrying, up to 1001bs in weight, can be turned invisible at will. Any object(s) exceeding the 100Ib weight limit will remain visible, but the person will still turn invisible. Neither normal vision nor nightvision can detect invisibility; however, infrared, heat sensors ~and motion detectors can easily locate an invisible interloper. Although the invisible character is imperceptible to the eye, he retains his physical mass, meaning that he can not go through walls nor do weapons pass through him. This also means he stil] makes noise (footsteps, breathing, bumps, knocks, etc.) and may be located by his noise if not careful. Note: The invisibility can be maintained indefinitely and created and cancelled at will. Other Abilities and Bonuses: Opponents who can not see the invisible person are - 6 to strike, parry or dodge him. Opponents with extraordinary senses of smell or hearing are - 3 to strike, parry and dodge him. Opponents with heat or infrared sensors or vision suffer no penalties. ; @ The character can automatically see the invisible. Add 1D4x 10 S.D.C.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Invulnerability', 'major', 'import', 'Revised Heroes Unlimited p.185', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'An impressive power that makes the character an almost indestructible juggernaut. Most physical attacks do no damage whatsoever! This means cold, fire, heat, electricity, lasers, other types of energy, bullets, punches, falls and so on, do NO damage! Gases, drugs, chemicals, poisons, toxins and radiation will affect the invulnerable person, but are reduced to half the usual potency (half damage, duration, effect). The character is only, truly, vulnerable to psionics, illusionary and spell magic, and magic weapons, all of which have full effect. Of course, energy type magic, like fire balls, does NO damage. Other Abilities and Bonuses: @ Add 4D6x 10 S.D.C. @ Add 1D6 to the P.E. attribute. Add 1D4 to the P.S. attribute. @ Add +20% to save vs coma/death (this is in addition to any P.E. bonus).');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Karmic Power', 'major', 'import', 'Revised Heroes Unlimited p.185', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'An unique power that can adjust the odds in the character''s favor. The character is able to influence his luck and those around him via a sort of Karmic aura. Karma is an energy of positive or negative affect. Theoretically, it is an aspect of the constant struggle between good and evil; order and chaos. This means that only characters with a good alignment, principled, scrupulous or unprincipled, can have this power. If your alignment is evil or anarchist, you must select a different super ability. When the cause is just, the motives good and/or selfless, the following bonuses apply to the character: +6 to roll with punch, fall or impact. +2 to strike. +4 to parry. +6 to dodge. +6 to save vs poison/toxins/gases. +6 to save vs psionics. +4 to save vs magic. +20% to save vs coma/death. Death blow does not kill; only stuns the character. Critical damage attacks do normal damage. 185 Knocks opponent unconscious on a roll of natural 20 to strike, 3D4 melees. + 10% on a skill if it is to save a life or help an important cause. Add 1D4x 10 S.D.C. Note: Opponents get no bonuses to strike, parry or dodge the Karmic character. Straight, unmodified dice rolls only. The Karmic power can also affect others if the Karmic character is concentrating on them. Through intense concentration the character can add bonuses or penalties to another character. However, he can not take any action, even to defend himself, that melee. Up to four people can be effected simultaneously as long as they are within 150ft (45.7m) of the character. Influencing thoughts and cheers can be like: "Come on, you can do it .." or "You can take that guy, I know it." Bonuses Possible for Others . . . +1 to strike. +2 to parry. ad +2 to dodge. +4 to roll with punch, fall or impact. +2 to save vs poison/toxins. + 10% to save vs coma and death. + 10% on a crucial skill action. Penalties Placed on Evil Opponents: - | to strike. - 2 to parry. - 2 to dodge. - 10% on a crucial skill action. Remember, these penalties apply only if the Karmic character is immobile and concentrating. Bad Karma occurs when the character does something cruel, unnecessarily mean, evil or anything strictly against his alignment. When this happens his personal karma bonuses become zero, A second act contrary to his alignment or horribly evil, like intentionally betraying a friend, will give the character all the penalties listed under evil opponents and no other bonuses via karmic powers.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Magnetism', 'major', 'import', 'Revised Heroes Unlimited p.185', 'heroes-unlimited', '160ft (48.8m)', 'Regulated by the character.', 'None', NULL, 'The power to direct, control, and manipulate aspects of magnetic forces. 1. Attract Metal Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. The character can attract or pull to him up to 3000lbs (1350kg). To magnetically affect the object, it must have at least a 20% iron/steel composition. The strength of the pull is equal to an attribute of P.S. 30 and can pull a metal item from up to 160ft away. Maximum Weight which can be attracted is 3000lbs (1350kg), plus 20lbs (9kg) per level of experience. The magnetic force can be focused on one specific target or a 160ft area, attracting everything that has metal. Thus, the character can pull a gun out of somebody''s hand, pull somebody to him by the belt buckle, pull a car door off it''s hinges, and so on. Each use of the magnetic force counts as one attack that melee. Hurl or Repel Metal Objects Range: 160ft(48.8m)+ 10ft (3m) per level of experience. Damage: Varies Duration: Regulated by the character. Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. In many ways, this ability is the reverse of the attract metal power. The character can repel objects which are at least 20% iron. This can be focused against one specific item or to repel any metallic objects within the 160ft (48.8m) area. The hurled objects can make excellent weapons. Damage from hurled objects. Tiny Items such as paper clips, keys, pens, bottle caps, and similar items, sting when they hit, but do no damage. Small Items weighing a half pound to one pound inflict 1D4 damage each. Small Items weighing two to six pounds inflict 1D6 damage. Medium Items weighing ten to twenty-five pounds inflict 2D6 damage. Large Items weighing thirty to sixty pounds inflict 3D6 damage each. Heavy Items weighing seventy to one hundred ten pounds inflict 6D6+4 damage each. Huge Items weighing one hundred twenty to three hundred pounds inflict 2D4 x 10 damage. Maximum amount of weight which can be magnetically affected is 400 pounds (189kg) plus 20 pounds (9kg) per level of experience. Note: For multiple object attacks it will be much quicker to use the Volley Combat Rules. Magnetic Field Range: Self or up to a 30ft area. By placing a magnetic field around himself the character can stop or deflect metal objects, including thrown items and even automobiles. The magnetic field will also erase any magnetic tapes (computer and video tapes included), disrupt electrical frequencies, and reduce electrical attacks by half (half damage). The character can also use the field to propel himself toward (or away from) any iron object that is at least equal to his own body weight. Maximum speed of travel is about 20mph, and has a very limited range of 160ft (48.8m) plus 10ft per level of experience. This same ability can enable the character to hover or appear to walk in mid-air. Magnetize Objects Range: Touch Duration: 2D4 days The super being can make an iron object temporarily magnetic. Magnetized items are much like the kind of magnets available in the commercial market. They are most suitable for attaching to iron or steel objects. The time required to magnetize an object is 5 minutes per every one pound of weight. Sense Iron Range: 160ft+ 20ft per level of experience. The magnetic empowered character can sense the presence (and vague location) of iron or steel within a 25ft radius. The exact size of the item or items is impossible to discern. Impressions will be felt as: much, little, none. Location will be sensed as: near or at the edge of the range. This ability can be used to detect objects/ore beneath the ground as well.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Mimic', 'major', 'import', 'Revised Heroes Unlimited p.186', 'heroes-unlimited', 'Touch or within a 60ft radius.', 'Special', NULL, NULL, 'This formidable power enables the super being to imitate or mimic another person''s physical and mental attributes (not skills or experience), psionics, abilities and innate magic abilities (not spell knowledge; just magic powers such as those gained from weapons, objects and bestowed). A mimic can not copy/absorb mechanical abilities like those gained through bionics or robotics; nor can he mimic skills, hardware or special training. Only the raw physical and/or extraordinary power can be imitated. Skills, education, memories, and experience can not be copied. Thus, while a mimic may copy a power, he does not get that person''s knowledge, but retains all of his own skill knowledge, training and memory. I don''t mean to be redundant, but I do not want this power misconstrued as something it is not. Example: A mimic copies the power of a sixth level mutant with the power of energy expulsion. This enables him to fire energy bolts doing damage equal to his sixth level opponent because that is the level of raw power. However, he does not have any bonuses to strike which may have been developed through experience. Likewise, while the mimic has copied his opponent''s entire physical structure, including physical strength, prowess, S.D.C. etc., the mimic does not have any bonuses to strike, parry, dodge, knock-out, additional attacks, etc., which were gained via hand to hand and other physical skills. Range: The mimic can imitate a person by touching him/ her or by being within close proximity; 60ft radius. If the person being copied should go beyond the 60ft radius, the imitated power will fade away. Duration: The power will disappear within two to eight minutes (roll 2D4) after the person being copied steps out of range. However, as long as the person is within the 60ft radius, the mimic retains his powers as long as desired. Switching to mimic a different person and abilities can be attempted once every melee, if so desired. Physical appearance of the mimic generally remains unaltered unless the person being imitated possesses an unusual physical trait such as wings, odd hair or skin color, horns, natural body armor, tail, etc. Even under these conditions the mimic will retain his own basic features, voice and abilities.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Mechano-Link', 'major', 'import', 'Revised Heroes Unlimited p.187', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'A bizarre ability that enables the character to link with any kind of machine so that man and machine becomes one. This means that vehicles respond to a mere thought, adding to their mobility, and weapons become more precise. Bonuses: +20% to all piloting skills. + 20% to all pilot related skills. +20% to computer, electrical and mechanical skills. +2 to strike with modern weapons including energy weapons. No bonuses on ancient. 60% base skill ability to understand and operate unknown or alien machines. 1. Computer Merge. The character can merge and communicate with any computer system regardless of preventative programs. The character has the ability to communicate directly with computers and computer-directed machinery. This also includes robots, modern cars (the ones with on-board computers) and computerized factories. The link can be as direct as touching the machine itself, or can be remote if the machine has some kind of modem (telephone) link. Once the link is established the character can examine any of the machine''s data or programming and can completely reprogram the machine. Performing a mechano-link with a sentient machine, one that has reached the level of self-programming and self-awareness, will mean the psionic can communicate with the machine''s intelligence. This does NOT include the ability to command machines. 187');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Plant Control', 'major', 'import', 'Revised Heroes Unlimited p.187', 'heroes-unlimited', '40ft (12.2m) + 10ft (3m) per additional level of ex- perience, at distances up to 100ft (30.5m) plus 10ft per level of experience away.', NULL, NULL, NULL, 'The character can direct, manipulate and grow plants at an astounding level. 1. 5. Animate and Control Plants The character can mentally manipulate all plant life within a 40ft radius around him. Thus, he can cause any vines, weeds, shrubs, or trees to trap and ensnare an animal, entangle someone, or cover something. He can also manipulate the larger plants to grab and hold something. Although the limbs of the plants can be made to move and function like hands and arms, they are still restricted to the fact that the'' plant is rooted in the soil. ; This control requires the full concentration of the character, preventing him from taking other actions. Notes on plants: Since the hero is likely to use this spell to impede movement and to attack, here are some basic statistics: Weeds, grass, soft plants: S.D.C. 1D6, inflicts no damage. Heavy weeds, vines: A.R. 5, S.D.C. 2D6, damage 1D6 per melee, +2 to strike. Bushes, shrubs, small trees: A.R. 6, S.D.C. 4D6+4, damage from strangle is 2D6 per melee or 1D4 damage for hitting or whipping. Average trees: A.R. 8, S.D.C. 4D6x 10, damage is 2D4 per each hit. Large trees: A.R. 10, S.D.C. 6D6 x 10, damage is 4D6 per hit. Maximum attacks by a plant per melee is six. All attacks must be within the character''s line of vision. Entanglement can be utilized within the entire radius of control, even outside the line of vision. Grow Plants at an Unbelievable Rate. The character can grow most plants and shrubs, from seed to maturity, in 1D4 melees. Trees and large tree-size plants grow at arate of 8ft (2.4m) per melee, up to 200ft (61m) tall. The growth is temporary, and the plants will return to their original size within 20 minutes or at the character''s command. Alter Wood The character can alter the strength of wood by increasing or decreasing its S.D.C. This applies to any kind of wood item; doors, ladders, chairs, tables, an area of floor, club, and so on. Items at one foot (.3m) can have their S.D.C. increased or reduced by 10. '' @ Items two to four feet (.6 to 1.2m) can be increased or reduced by 30 8.D.C. @ Items or areas of wood five feet to ten feet (1.5 to 3m) can be increased or decreased by 100 S.D.C. Wither Plants This is the ability to wither or kill plants. Area of affect is a 20ft radius. Plants can be withered once per melee. Range: 20ft away (6.1m) + 10ft per level of experience. Other Abilities and Bonuses. @ Recognize and Identify Plants - 88% @ +10% to prowl skill when outdoors. @ + 10% to climb trees or vines. Add 1D4~x 10 to S.D.C.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Shape Change', 'major', 'import', 'Revised Heroes Unlimited p.188', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'These masters of disguise can actually change all aspects of their physical appearance: height, weight, features, hair, eyes, skin color, etc. Voice imitation is not included, but a 15% bonus can be applied to the imitate voices skill. Large extra appendages, such as wings and extra limbs, can not be imitated; however, tails, horns, claws, fangs, etc., can all be grown. ALL changes are REAL physical changes, not just clever make-up. A shape-changer can transform into any humanoid creature, including apes. Size Limit: No smaller than 2''/ feet tall and no larger than 12 feet tall. No damage or dodge bonuses apply when large or small.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Shrink', 'major', 'import', 'Revised Heroes Unlimited p.188', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'The power to shrink blatantly defies the laws of physics, enabling the character to greatly reduce his size and mass. First, players roll to determine the minimum size the character can shrink down to. Note: The super being has total control over his shrinking power and can stop at any size not exceeding his minimum limitation. NO the character can not reverse the process and grow giant. He can resume his normal size at any time. Natural Minimum Prowl Ability 1-24 Six inches 50% 25-50 One inch 70% 51-75 ''Yofaninch 90% 76-00 Fullrange 6in.-Ysin. Varies with size The prowl ability only applies when shrunken. If a prowl skill is also chosen add a 20% bonus to the prowl ability (to all except % of an inch which remains 90%) when tiny. Second, the player rolls to determine whether or not the character''s mass is altered when reduced. This determination is crucial in defining the character''s powers. Mass Table 1-50 Mass is reduced with size. 51-00 Mass is constant/unchanged. Bonuses: +6 to dodge. Disadvantages: - 5 to strike large opponents. - 10 to parry large objects/opponents. All distances and speeds are reduced from feet or yards to inches. Constant Mass or unchanged mass is truly unique, for even though the person shrinks to the size of a bug, he retains ALL his original weight/mass and physical strength. Can you imagine the surprise when an opponent tries to grab the tiny super being and can not because he still weighs 180lbs? OR an opponent tries to step on the little guy and is instead knocked down or tripped by him? Speed is still reduced just because of the character''s tiny size. Same as listed under reduced mass. Physical Strength is unchanged. The tiny character does full normal damage plus any P.S. attribute bonuses. Body blocks against legs and ankles are very effective against op- 188 ponents, doing full damage (1D6). Tripping is also effective. Ignoring the conditions of leverage, the tiny person can throw knives, bricks, objects, overturn tables and chairs, and so on. Range of thrown objects is limited to a maximum of 12 feet. Wind does not affect this miniature person; thus, he can not glide on wind currents. Other abilities include leaps of up to 4ft high and 4ft long. Hold doors closed or objects down by leaning full weight against it. He/she CAN NOT hitch rides on animals or people; too heavy. However, they can hitch rides on vehicles such as cars, trucks, etc. Bonus: +6 to dodge. Disadvantages: - | to strike. ? All distances and speeds are reduced from feet to inches. Note: Objects/weapons do not shrink with the person. Reduced mass means that the super being''s mass/weight is reduced along with the size. Reduce the weight by 25% for each 12 inches reduced. At six inches the weight is four ounces; at one inch tall the weight is half an ounce; at one eighth of an inch the weight is a mere fraction of an ounce, virtually weightless. Speed is converted from feet/yards traveled per minute to inches per minute. Six inches tall: Spd x 20 = How many inches per minute can be run. One eighth of an inch: Spd x 10=How many inches per minute can be run. Physical strength is reduced. Six inches tall: P.S. is on half; One inch tall: P.S. is reduced to one third; and at One eighth of an inch: P.S. is reduced to one quarter. S.D.C. in all cases are reduced by half when reduced. Other abilities of these tiny heroes include the ability to attach or hold onto an animal, shoe, pant leg, etc., unnoticed, for a free ride. Likewise, they can hide inside a pocket or small container. These and their prow! ability makes them formidable spies (i.e., escape bonds by shrinking). At one inch or smaller the super being can glide on air currents/wind, under 8mph, at a rate of ten feet per melee (15 seconds). Stronger winds are dangerous, preventing controlled gliding. There is a 65% chance of being carried off in the opposite direction, as well as a 50% chance of being dashed into the ground, a wall, or other object, taking 4D6 points of damage. Roll once every minute to determine the effects of the wind current.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Sonic Power', 'major', 'import', 'Revised Heroes Unlimited p.188', 'heroes-unlimited', '1000ft (305m) + 100ft per level of experience. Loudness or intensity of loudness is measured in decibels. This super being can hear even a one decibel sound at a great distance (1000ft). This enables him to: Estimate the distance of the sound - 50%+10% per level; Estimate speed of approach/departure - 40% + 10% per level; Recognize the type of sound - 50% + 10% per level; Pinpoint the exact location of sound - 22% + 8% per level. Minuses to strike, parry and dodge in darkness or while blinded or attacking the invisible, are all reduced by half. Example: - 8 to strike, parry and dodge while blind is reduced to - 4.', 'Instant', '1D6 per melee.', NULL, 'The ability to manipulate and control aspects of sound. 1. Hear Wider Spectrum of Sound The Decibel Scale A 20 decibel sound is 10 times louder than a 10 decibel sound: 30 decibels is 100 times louder; 40 decibels is 1000 times louder, etc. One decibel: The smallest difference between sounds detectable by the human ear. 10 decibels: A light whisper. 20 decibels: A quiet conversation. 30 decibels: A normal conversation. 40 decibels: Light traffic. 50 decibels: Loud conversation. 60 decibels: Shouting 70 decibels: Heavy traffic. 80 decibels: Loud noise, subways, rock concerts. 90 decibels: Very loud; thunder. 100 decibels: Jet plane take-off; temporarily deafening. 140 decibels: Extremely loud, painful, deafening. Sound waves travel better and faster through solids and water because of the denser molecules. Thus, the character can hear clearly through walls by leaning his ear against the wall or floor. Note: The range of all hearing abilities are reduced by half in the city during the day. Emit Highpitched Whine Range: 180ft Area Affected: 30ft radius, with hero as focal point. This ability enables the character to emit a highpitched frequency or whine which will hurt, deafen and distract all who fall prey to it. Victims are - 6 on initiative, and - 6 to strike, parry and dodge. Victims also take 1D6 points of damage each melee round (subtract damage from S.D.C. first). The only defense is to plug the ears. Plugging ears (both must be plugged) with fingers reduces damage and minuses by half, but also prevents any counterattacks except psionic. Plugging ears with cotton, tissue or cloth reduces the damage by half and minuses by one. Ear plugs will prevent any damage and reduce minuses by half. 189 Note: The hero must concentrate to maintain the sound frequency and can not use any other sonic power simultaneously. However, the character can engage in hand to hand combat without penalty. 3. Sonic Boom or Blast Range: 200ft Damage: 1D4x 10 Attacks Per Melee: Equal to the character''s total hand to hand melee attacks. This is a blast or bolt of concentrated sound waves. Add +10 to the damage for any attacks underwater. 4. Other Abilities and Bonuses @ +1 to strike Add 1D4~x 10 S.D.C. @ +1 to parry and dodge. @ +2 on initiative. 5. Sonar Range: 400ft+ 100ft per level of experience. This is the emitting of high-frequency sound waves underwater which bounce off objects, returning and indicating the direction and distance of the reflecting objects. The abilities include: Interpreting shapes: 50% + 8% per level of experience. Estimating Distance: 60% + 8% per level of experience. Estimating Direction: 50% + 8% per level of experience. Estimating Exact Location: 34% + 8% per level of experience.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Sonic Speed (running)', 'major', 'import', 'Revised Heroes Unlimited p.189', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'The power to run at supersonic speeds. This means the character can run at the speed of sound, Mach One, or approximately 670mph (1078kmph). That''s a little less than one mile every five seconds and 11 miles per minute. In addition to running at incredible speed the character has sharper vision, quicker reactions and greater dexterity than normal humans. Despite what one might think, super speed in hand to hand combat requires a comparatively slower, more measured, and controlled pace. The results are still devastating. Other Abilities and Bonuses Add two attacks per melee, plus add one more attack per melee at level three. Add 4D4 x 10 to S.D.C. Add 1D6 to P.E. attribute. +6 on initiative. +1 to strike +4 to parry +6 to dodge +6 to roll with punch, fall or impact. Normal fast punch - 1D6 damage. Super fast power punch - 4D6 damage. Counts as two attacks. @ Normal fast kick - 2D6 damage. Super fast power kick - 6D6 damage. Counts as two attacks. Leap ability - 60ft (18.3m) straight up and 100ft (30.5m) lengthwise. Body block/ram at 400mph or greater does 1D6 x 10 damage, but the character also takes 5D6 damage. Counts as three attacks. @ Superior vision about five times better than normal humans, which means an 18 inch sign can be read a mile away. @ Nightvision - 500ft (152.5m).');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Sonic Flight', 'major', 'import', 'Revised Heroes Unlimited p.190', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'The power to fly at the speed of sound, Mach One. That''s approximately 670mph, or about 11 miles per minute or one mile every 5 seconds. The sonic flight ability also gives the character superior vision, dexterity and reflexes. However, unlike the sonic speed power the thrust of this ability is flight and not overall speed. Thus, its bonuses are nowhere near as impressive as the sonic speeds. Other Abilities and Bonuses @ Add one extra attack per melee. Add 3D4 x 10 .D.C. Add 1D4 to P.E. attribute. +2 on initiative (applies at all times). +1 to strike while in flight only. +2 to parry while in flight only. +6 to dodge while in flight only. Sonic two-fisted punch (ram style) at 400mph or greater inflicts 1D4 x 10 damage to one''s opponent and 3D6 to the sonic character. Counts as two attacks. Sonic flying body block/ram at 400mph or greater inflicts 1D6 x 10 damage, but the sonic character also takes 5D6 damage himself. Counts as three attacks. Extraordinary vision TEN times greater than a normal humans (about equal to an eagle), which means an 18 inch object can be seen, with perfect clarity , two miles away. @ Nightvision - 1000ft (305m).');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Stretching (elasticity)', 'major', 'import', 'Revised Heroes Unlimited p.190', 'heroes-unlimited', NULL, NULL, NULL, NULL, 'This is a very interesting power because it has several, uniquely different, applications. The power makes the character''s body super elastic and malleable, enabling him to distort and elongate limbs or the entire body. 1. Stretching Neck: 4ft (1.2m) Finger: 4ft (1.2m) Arm(s): 20ft each (6.1m) Leg(s): 35ft each (10.7m) Body (maximum length): 150ft (45.7m) 2. Stretching Contortions Flatten the entire body to as little as 2 inches thick, but like clay flattened by a rolling pin, the rest of the body mass is pushed out four feet for every 60lbs (27kg) of normal weight. Condense the entire body into a compact ball of one and a half feet/18 inches (.5m). 3. Bounceability The character can puff hiinself up like a balloon and bounce. In this form, punches, kicks, collisions, explosive force and falls do NO damage. The height of a bounce selfinitiated from ground level is about six feet (1.8m) to twelve feet (3.4m). Propelling himself with his elongated arms and bouncing will triple his normal speed. 4. Special Maneuvers Gliding is possible by flattening one''s arms and/or legs, or body, to catch the wind and float on air currents. Average gliding speed is 8mph (12kmph); the maximum possible if dropped from an airplane or great height (300ft or higher) is 20mph (32kmph). The old rope trick is the character using his arm or body as a lasso to snare and tie up an opponent. The squeeze play is a variation on the rope trick in which the snared and entangled opponent is squeezed as the character contracts his body. Yes, this can kill, but good aligned characters will never use this ability to torture or kill. Damage is 2D4 per melee. 5. Other Abilities and Bonuses @ Add 2D4 x 10 S.D.C. @ Add 1D6 to P.E, attribute. . @ +1 to strike. : 4 @ +2 to parry and dodge. @ +3 to roll with punch, fall or impact. Projectiles, such as bullets, arrows, thrown objects, punches and kicks, all do half damage. Energy attacks, psionics and magic do FULL damage.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Teleport', 'major', 'import', 'Revised Heroes Unlimited p.190', 'heroes-unlimited', 'Maximum distance of 5 miles.', 'Instant', NULL, NULL, 'The super being can instantly transport himself from one location to another in the blink of an eye. Weight Limitation: Self and an additional 1000lbs. Number of Teleports per Melee: One. While teleportation can be very handy, it can also be extremely dangerous, especially if the area teleported to is unknown. Chances for a Successful Teleport: @ Teleporting to a familiar location, or one that is clearly visible from your starting point: 99%. A place seen only a few times (2-6 times before): 88%. @ A place never seen, but described in detail: 38%. @ A totally unknown place: 12%. Results of an Unsuccessful Teleport 1-60 Totally wrong place. No idea of present location; 20-80 miles beyond the normal range. (roll 2D4). 61-85 Teleport 300ft above ground level; fall does 1D6 damage for every 30ft of height (that''s 10-60 damage). 86-00 Teleport into an object; instant death.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Transferal/Possession', 'major', 'import', 'Revised Heroes Unlimited p.190', 'heroes-unlimited', '30ft (9.1m) + 10ft per each additional level of experi- ence.', 'The transferal is instant and the character can main- tain the possession indefinitely.', 'None', NULL, 'Attacks Per Melee: One attempt per melee. This devastating power enables the character to transfer his consciousness into another person''s body. Once inside another''s body he completely takes over, suppressing the consciousness and personality of his host body. The memories and thoughts of the person being possessed are still his own and can not be read by the possessing character. Likewise, the possessed person can not read the thoughts of the entity who has temporarily seized control of his body. In fact, the person will have no recollection of events which occurred while his body was controlled by another. It will be as if he fell asleep the whole time. Any reports of heroics or uncharacteristic actions will come as a complete surprise. When inside another body, the character retains only his own memories, personality and skills. Any other super ability or special physical attributes are left in his own body and are totally unusable. Only the abilities of the host body can be used. This means, if the body is weak, slow, or physically undeveloped, that acrobatics gymnastics and hand to hand combat may be out of the question. The typical person has one attack per melee. The hero''s knowledge of hand to hand combat will increase that to two or three, as well as other hand to hand combat bonuses. However, bonuses the character is used to, from high attributes, super abilities and other physical traits, will not apply to the host body. The game master will help establish the physical condition and aptitude of the host body. Of course, if a super being is possessed, the character can use his powers, but all bonuses are half due to lack of experience. What happens to the character''s real body while he possesses another body? Good question. The body drops into a dreamless, sleep-like trance. Without a mind to control it, the body is just an empty shell. As you might think, this leaves it defenseless against attacks and the elements. Thus, it is wise to leave the body with friends who can protect it, or in as safe and hidden a place as possible. Note: The abandoned body is totally defenseless against psionics, magic, or being possessed itself (no savings throws apply). Other Abilities and Bonuses @ +6 to save vs being possessed himself (counts only when inside his body). +2 to save vs all mind control powers. @ Add 1D4 to M.E. @ Add 1D4x 10 to S.D.C.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Vibration', 'major', 'import', 'Revised Heroes Unlimited p.191', 'heroes-unlimited', '120ft+ 10ft per level of experience.', 'Instant', '1D8 per each level of experience.', NULL, 'The manipulation of vibration and air flow. 1. Shock Waves Attacks Per Melee: Two Bonus: +2 to strike. The super being is able to create shock waves to that ripple through the earth, cracking sidewalks, walls, buildings, etc. Damage: Is inflicted to everything within the path of the shock wave. Range: Up to a maximum of 120ft+ 10ft per each level of experience. The width of the shock wave is six feet. The character can control the range to a few feet or to the maximum distance. 2. Shock Blast Range: 200ft (61m) Damage: 4D6 Duration: Instant 191 Attacks Per Melee: Equal to the character''s hand to hand melee attacks. Bonus: +4 to strike. An amplified bolt of force that can be fired like an invisible concussion blast. 3. Vibrate Through Substances Range: Self Duration: As long as necessary. The character can make his body vibrate so quickly that he is able to pass through solid matter. The only limitations are that he can only vibrate through inorganic (non-living) material, such as rock, concrete, processed wood, steel, etc., and speed is reduced to one third normal. 4. Vibrate to Become Intangible Range: - Self Duration: One minute for every P.E. attribute point. Attacks Per Melee: Takes the place of ALL attacks that melee. The character can vibrate so fast that any physical attacks, such as bullets, knives, punches, etc., pass harmlessly through him. Energy attacks, fire, electricity, etc., do one third normal damage. NOTE: The character is also semitransparent when intangible. 5. Feel Vibrations Range: 30ft (9.1m) +5ft (1.5m)per level of experience. The character is so sensitive to vibrations that he can physically feel changes in air currents caused by the movement of others. This means he can NOT be snuck-up on or caught by surprise from a nearby opponent (long-range blasts and bullets are effective because of their great speed). This also means the character is like a living motion detector; able to sense the presence of nearby movement and even estimate their numbers and speed of approach. 66% accuracy in estimates. Bonuses: + 2 to parry +2 to dodge +6 on initiative 6. Other Abilities and Bonuses @ Add 1D6x 10 S.D.C. Double normal speed attribute.');

INSERT INTO super_abilities
  (name, tier, source, source_book, system, range, duration, damage, saving_throw, description)
VALUES ('Weight Manipulation', 'major', 'import', 'Revised Heroes Unlimited p.191', 'heroes-unlimited', 'Self or 100ft (30.5m) + 10ft per level of experience.', 'Special', NULL, NULL, 'Attacks Per Melee: Equal to the character''s hand to hand melee attacks. This power enables the character to reduce or increase the mass of organic and inorganic matter. This has dozens of applications. By reducing the weight of objects, he can carry what might normally have been a thousand pounds as if it were 20. On the other hand he can make a key weigh 100lbs (45kg). Making an opponent heavy will slow him down or even cause him to fall through the floor. Limitations: 1. Each weight increase or decrease attack has a maximum of one hundred pounds. This means, if a character has FOUR hand to hand attacks per melee, he can opt to use his weight = = - - - - 192 \ \ 4. SOME EFFECTS OF NOTE: ; Weightlessness is being effectively without weight. This means power four times, decreasing or increasing the weight of an object up to 400lbs (100lbs per each attack) per melee. Attacks must be directed at one person or item at a time. No simultaneous multiple attacks. Duration is six minutes on an unfocused attack, or indefinitely if the character is intentionally concentrating to maintain the weight change. Subtract one attack per melee if concentrating to maintain an effect. Maximum weight increase is 10,000 pounds (5 tons). victims of weightlessness will float and bob along 1D4 feet above the ground, speed is reduced to''a speed factor of 1, and wind will float them away. Unless the victim possesses some means of flight or gliding (telekinesis, gravity manipulation and magnetism included), he is minus - 5 to strike, parry and dodge, and loses one attack per melee. The character can master weightlessness to make himself glide on air currents at speeds of 8 to 18mph (12kmph to 29kmph). No special bonuses apply to gliding flight. Increased Weight will also increase one''s S.D.C. 20 per each 100lbs because of the increased mass. If regulated just right, this can help the character out in many situations, especially if he wishes to become an immovable object himself. The punch of the heavier character does more damage. Add 1D4 per each 100lbs (45kg), to a maximum of 800lbs (8D4). After 800lbs the character can barely lift his arms, all physical attacks/actions are reduced to two per melee, and speed is reduced to a speed factor of 3. No significant movement is possible after 1400lbs. Note: The S.D.C. of one''s opponent is also increased by 20 S.D.C. per each 100]bs of weight.');

-- ASSERTIONS. Each batch asserts its own rows and nothing else.

SELECT 'sixty-nine rows cite the Revised core' AS assertion,
       count(*) AS got, 69 AS want
  FROM super_abilities WHERE source_book LIKE 'Revised Heroes Unlimited%';

SELECT 'thirty-one are minor' AS assertion, count(*) AS got, 31 AS want
  FROM super_abilities
 WHERE source_book LIKE 'Revised Heroes Unlimited%' AND tier = 'minor';

SELECT 'thirty-eight are major' AS assertion, count(*) AS got, 38 AS want
  FROM super_abilities
 WHERE source_book LIKE 'Revised Heroes Unlimited%' AND tier = 'major';

SELECT 'every one is tagged heroes-unlimited' AS assertion, count(*) AS got, 69 AS want
  FROM super_abilities
 WHERE source_book LIKE 'Revised Heroes Unlimited%' AND system = 'heroes-unlimited';

SELECT 'every one carries a real description' AS assertion, count(*) AS got, 69 AS want
  FROM super_abilities
 WHERE source_book LIKE 'Revised Heroes Unlimited%'
   AND description IS NOT NULL AND length(description) > 40;

SELECT 'the indexed spellings are stored, not the headings' AS assertion,
       count(*) AS got, 5 AS want
  FROM super_abilities
 WHERE name IN ('Impervious to Fire & Heat', 'Super Vision: Ultraviolet & Infrared',
                'Control Elemental Force: Earth', 'Control Others', 'Shape Change');

SELECT 'Weight Manipulation came from printed 191, not the roster on 169' AS assertion,
       count(*) AS got, 1 AS want
  FROM super_abilities
 WHERE name = 'Weight Manipulation'
   AND source_book = 'Revised Heroes Unlimited p.191';

-- Tests the FAULT, not a threshold: a truncating generator leaves descriptions
-- sitting at exactly the cap. Counting rows ABOVE 4000 was the first version of
-- this and it was wrong - the stored description also prepends Bonuses/Note, so
-- eight rows clear 4000 where seven of the raw extracts did.
SELECT 'no description was truncated at the old 4000-char cap' AS assertion,
       count(*) AS got, 0 AS want
  FROM super_abilities
 WHERE source_book LIKE 'Revised Heroes Unlimited%' AND length(description) = 4000;

SELECT 'no row outside this book was written' AS assertion, count(*) AS got, 0 AS want
  FROM super_abilities
 WHERE source_book LIKE 'Revised Heroes Unlimited%' AND source <> 'import';

